import type { LaBai } from '@/lib/tarot';

export const MAU_LA_BAI: LaBai[] = [{"ma":"major-00","bo":"Ẩn Chính","so":0,"tenVi":"Gã Khờ","tenEn":"The Fool","tuKhoa":"Khởi đầu, liều lĩnh, ngây thơ","yNghiaXuoi":"Chàng trai bước tới sát mép vực mà mắt vẫn ngước lên trời, tay ôm bông hoa trắng, con chó nhỏ dưới chân sủa inh ỏi. Bạn đang đứng trước một việc hoàn toàn mới và chưa biết nó dẫn tới đâu, nhưng chưa có gì để mất lại chính là điểm mạnh lúc này.","yNghiaNguoc":"Vẫn bước chân ấy nhưng không ai cảnh báo. Bạn lao theo cơn hứng rồi mới hỏi mình đang làm gì, hoặc ngược lại, đứng mãi ở mép vực tới lúc cơ hội trôi qua.","tinhCam":"Mới chớm, còn nhẹ và chưa ràng buộc. Vui thì vui, nhưng chưa có gì chắc chắn.","congViec":"Một cơ hội tới sớm hơn mức bạn thấy mình sẵn sàng. Thiếu kinh nghiệm không phải lý do để từ chối.","loiKhuyen":"Cứ bước đi, nhưng nhìn xuống chân trước khi nhảy."},{"ma":"major-01","bo":"Ẩn Chính","so":1,"tenVi":"Nhà Ảo Thuật","tenEn":"The Magician","tuKhoa":"Chủ động, khéo léo, biến ý thành việc","yNghiaXuoi":"Trên bàn có đủ bốn thứ, gậy, cốc, kiếm và đồng tiền, nghĩa là không thiếu gì cả. Người đàn ông một tay chỉ trời một tay chỉ đất. Bạn đã có đủ khả năng và điều kiện cho việc đang định làm, giờ chỉ còn thiếu một điều là bắt đầu.","yNghiaNguoc":"Đồ nghề vẫn bày ra đó mà bàn tay buông thõng. Bạn đang để phí khả năng của mình, hoặc đem nó ra loè người thay vì làm thật. Cũng có thể quanh bạn đang có kẻ nói hay hơn làm.","tinhCam":"Bạn đang có sức hút. Đây là lúc nói thẳng điều mình muốn, đừng chờ người kia tự đoán ra.","congViec":"Chào hàng, thương lượng hay mở việc riêng đều thuận. Người ta đang nhìn thấy bạn.","loiKhuyen":"Đừng chờ thêm điều kiện nào nữa. Thứ còn thiếu là bạn bắt tay vào."},{"ma":"major-02","bo":"Ẩn Chính","so":2,"tenVi":"Nữ Tư Tế","tenEn":"The High Priestess","tuKhoa":"Trực giác, im lặng, điều chưa lộ","yNghiaXuoi":"Bà ngồi giữa hai cột đen trắng, sau lưng là tấm màn che kín, cuộn sách trong lòng chỉ hé ra một nửa. Chuyện bạn đang quan tâm còn phần chưa ai nói ra. Những gì bày trước mắt mới là một nửa sự thật.","yNghiaNguoc":"Tấm màn bị vén lên không đúng lúc. Điều giấu kín sắp lộ, hoặc chính bạn đang bịt tai trước linh cảm của mình.","tinhCam":"Người kia chưa nói hết lòng. Càng ép thì họ càng đóng chặt.","congViec":"Chưa đủ thông tin để quyết. Hỏi thêm, quan sát thêm, đừng ký gì trong tuần này.","loiKhuyen":"Điều bạn linh cảm thường đúng hơn điều người ta nói với bạn."},{"ma":"major-03","bo":"Ẩn Chính","so":3,"tenVi":"Nữ Hoàng","tenEn":"The Empress","tuKhoa":"Sung túc, chăm sóc, sinh sôi","yNghiaXuoi":"Bà ngả người trên gối giữa cánh đồng lúa chín, suối chảy sau lưng, cây cối rậm rạp quanh mình. Thứ gì bạn gieo trong thời gian qua cũng đang lớn. Giờ là lúc gặt, đừng gieo thêm.","yNghiaNguoc":"Cánh đồng vẫn xanh nhưng người trông nó thì kiệt sức. Bạn lo cho người khác tới mức quên mình, hoặc bao bọc chặt tới mức họ thấy ngộp. Cũng có thể là giai đoạn cạn ý tưởng, làm gì cũng thấy khô.","tinhCam":"Nồng ấm và có chiều sâu. Có thể là tin vui về gia đình hoặc con cái.","congViec":"Công việc vào độ chín, thành quả bắt đầu thấy được. Hợp với nghề sáng tạo.","loiKhuyen":"Cho phép mình hưởng thứ đã gây dựng, đừng lúc nào cũng lo chặng sau."},{"ma":"major-04","bo":"Ẩn Chính","so":4,"tenVi":"Hoàng Đế","tenEn":"The Emperor","tuKhoa":"Kỷ luật, quyền lực, khuôn khổ","yNghiaXuoi":"Ngai bằng đá, bốn góc chạm đầu cừu, phía sau là núi trọc không một bóng cây. Việc bạn đang làm cần trật tự. Nó cần một người chịu trách nhiệm, chứ không cần thêm cảm hứng.","yNghiaNguoc":"Ngai vẫn đó nhưng không ai muốn lại gần. Bạn cứng tới mức không nghe được góp ý, hoặc ngược lại, buông lỏng tới mức chẳng ai cầm trịch.","tinhCam":"Một người vững vàng và đáng dựa, chỉ hơi khô khan. Lúc này cần rõ ràng hơn là cần lãng mạn.","congViec":"Lập kế hoạch, siết quy trình, nhận vai quản lý. Làm tới nơi tới chốn sẽ được ghi nhận.","loiKhuyen":"Đặt ra khuôn khổ cho chính mình trước, rồi hãy đòi hỏi người khác."},{"ma":"major-05","bo":"Ẩn Chính","so":5,"tenVi":"Giáo Hoàng","tenEn":"The Hierophant","tuKhoa":"Truyền thống, chỉ dẫn, khuôn phép","yNghiaXuoi":"Dưới bậc thềm có hai người quỳ nghe giảng, người giảng thì đã đi qua con đường đó rồi. Việc bạn đang vướng đã có người giải quyết rồi. Đi theo cách đã được kiểm chứng sẽ nhanh hơn tự mò.","yNghiaNguoc":"Hai người đứng dậy bỏ ra ngoài. Đã tới lúc làm theo cách của mình. Nhưng cũng coi chừng bạn chống một khuôn phép chỉ vì nó cũ, chứ chưa kịp nghĩ nó đúng hay sai.","tinhCam":"Chuyện đi theo hướng chính thức, chẳng hạn ra mắt gia đình, đính hôn, cưới xin.","congViec":"Nên tìm người dẫn dắt hoặc theo một quy chuẩn sẵn có. Chưa phải lúc phá lệ.","loiKhuyen":"Hỏi người đã đi qua chuyện này. Bạn không cần phát minh lại từ đầu."},{"ma":"major-06","bo":"Ẩn Chính","so":6,"tenVi":"Tình Nhân","tenEn":"The Lovers","tuKhoa":"Lựa chọn, gắn kết, thuận lòng","yNghiaXuoi":"Thiên thần giang tay phía trên, hai người đứng dưới, mỗi bên một cái cây. Bạn đang đứng trước một lựa chọn chạm vào thứ mình tin chứ không chỉ là tính hơn thiệt. Cũng có thể là lúc hai người thật sự hiểu nhau.","yNghiaNguoc":"Hai người cùng nhìn về hai hướng khác nhau. Lệch pha, hiểu lầm, hoặc một quyết định đưa ra vì sức ép chứ không phải vì bạn muốn.","tinhCam":"Sâu sắc và đồng điệu. Cũng có thể là lúc phải chọn giữa hai người.","congViec":"Hai ngả đường. Chọn cái hợp với con người bạn, đừng chọn cái trông sáng hơn.","loiKhuyen":"Chọn bằng lòng mình, rồi đừng ngoái lại."},{"ma":"major-07","bo":"Ẩn Chính","so":7,"tenVi":"Cỗ Xe","tenEn":"The Chariot","tuKhoa":"Quyết tâm, thắng lợi, giữ hướng","yNghiaXuoi":"Hai con nhân sư một đen một trắng kéo về hai phía khác nhau, mà người đánh xe không hề cầm dây cương. Ông giữ chúng bằng ý chí. Bạn thắng được việc này nếu không để mình bị kéo lệch khỏi hướng đã chọn.","yNghiaNguoc":"Hai con vật thắng thế và xe quay vòng tại chỗ. Bạn mất hướng, hoặc lao đi mà quên mất đang tới đâu. Có khi là dùng sức ép để đạt mục tiêu rồi nhận lại sự chống đối.","tinhCam":"Cần chủ động và dứt khoát. Lấp lửng lúc này sẽ làm hỏng chuyện.","congViec":"Vượt được cạnh tranh nhờ tập trung. Đừng ôm nhiều việc cùng lúc.","loiKhuyen":"Thắng lợi thuộc về người giữ được hướng đi, không phải người chạy nhanh nhất."},{"ma":"major-08","bo":"Ẩn Chính","so":8,"tenVi":"Sức Mạnh","tenEn":"Strength","tuKhoa":"Mềm mỏng, kiên nhẫn, làm chủ mình","yNghiaXuoi":"Người phụ nữ khép miệng con sư tử bằng hai bàn tay, không dây trói cũng không roi. Trên đầu cô là dấu vô cực. Chuyện trước mặt chỉ giải quyết được bằng sự điềm tĩnh, càng dùng sức càng hỏng.","yNghiaNguoc":"Con sư tử giành lại thế. Bạn cạn kiên nhẫn và dễ nổi nóng, hoặc tự nghi ngờ tới mức không dám làm gì. Bên trong mệt hơn vẻ ngoài nhiều.","tinhCam":"Yêu bằng sự bao dung. Nhẫn với tật của người kia thay vì đòi họ đổi ngay.","congViec":"Giữ được thái độ trong lúc căng thẳng sẽ đưa bạn đi xa hơn tài năng.","loiKhuyen":"Thứ bạn cần khuất phục là cơn nóng của chính mình, không phải người kia."},{"ma":"major-09","bo":"Ẩn Chính","so":9,"tenVi":"Ẩn Sĩ","tenEn":"The Hermit","tuKhoa":"Lui về, tự soi, tìm câu trả lời","yNghiaXuoi":"Một ông già đứng trên đỉnh tuyết, tay giơ cây đèn có ngôi sao bên trong, nhưng ông không soi cho ai cả mà soi đường mình đi. Bạn cần một quãng ở riêng. Chưa nhìn rõ mình đang ở đâu thì đi tiếp cũng bằng thừa.","yNghiaNguoc":"Đèn tắt, hoặc ông ở trên đỉnh lâu tới mức quên đường xuống. Ở một mình thành ra lạc lõng và từ chối mọi lời khuyên. Cũng có thể là đã tới lúc quay lại với mọi người.","tinhCam":"Cần khoảng lặng. Có thể là quãng xa cách, hoặc chủ động ở một mình để hiểu lòng mình.","congViec":"Chưa phải lúc mở rộng. Ngồi lại xem xét cái đang có trước đã.","loiKhuyen":"Câu trả lời nằm trong chỗ yên tĩnh, không nằm trong lời khuyên của đám đông."},{"ma":"major-10","bo":"Ẩn Chính","so":10,"tenVi":"Bánh Xe Số Phận","tenEn":"Wheel of Fortune","tuKhoa":"Xoay vần, thời vận, bước ngoặt","yNghiaXuoi":"Bánh xe quay, có con leo lên có con tụt xuống, và không con nào điều khiển được nó. Chuyện sắp tới phần lớn nằm ngoài tay bạn. Việc của bạn là xoay xở với cái đến chứ không phải chọn cái đến.","yNghiaNguoc":"Bánh xe vẫn quay nhưng đang quay về phía bạn không thích. Hoặc bạn cứ lặp mãi một vòng cũ mà không thoát ra được.","tinhCam":"Có biến chuyển bất ngờ theo hướng tốt lên. Người cũ có thể quay lại.","congViec":"Một cơ hội tới đúng lúc, hoặc một thay đổi bạn không lường trước. Đón lấy nó.","loiKhuyen":"Cái đang tới không do bạn gọi, nhưng nhận hay không là do bạn."},{"ma":"major-11","bo":"Ẩn Chính","so":11,"tenVi":"Công Lý","tenEn":"Justice","tuKhoa":"Công bằng, nhân quả, sự thật","yNghiaXuoi":"Một tay cầm cân, một tay cầm kiếm. Cân để đo cho đúng, kiếm để cắt cho dứt. Việc bạn đang chờ sẽ được phân xử đúng như nó vốn có, kể cả phần bạn không muốn nghe.","yNghiaNguoc":"Cân lệch hẳn về một bên. Có chỗ không sòng phẳng, hoặc bạn đang né trách nhiệm cho việc mình gây ra. Cũng có khi chính bạn chịu thiệt mà chưa lên tiếng.","tinhCam":"Cần sòng phẳng và nói thật. Quan hệ chỉ bền khi hai bên cho đi ngang nhau.","congViec":"Hợp đồng, thoả thuận, kiện tụng đều sẽ ngã ngũ theo lẽ phải. Đọc kỹ điều khoản.","loiKhuyen":"Bạn nhận về đúng thứ mình đã gieo, không hơn không kém."},{"ma":"major-12","bo":"Ẩn Chính","so":12,"tenVi":"Người Treo Ngược","tenEn":"The Hanged Man","tuKhoa":"Dừng lại, đổi góc nhìn, chịu thiệt","yNghiaXuoi":"Người treo ngược trên cây, một chân gập lại, mặt vẫn bình thản và quanh đầu có vầng sáng. Ông ở đó vì tự chọn chứ không phải bị trói. Việc của bạn đang đứng im, và lúc này đứng im lại đúng hơn là cố đẩy.","yNghiaNguoc":"Treo mãi mà chẳng thấy gì khác đi. Bạn chờ đợi vô ích rồi gọi đó là kiên nhẫn, hoặc hy sinh cho một thứ không ai ghi nhận.","tinhCam":"Một bên đang chịu nhiều hơn hẳn. Nhìn lại xem sự chờ đợi này có đáng không.","congViec":"Kế hoạch bị treo, ép cũng không chạy. Dùng quãng này xem lại cách làm.","loiKhuyen":"Thứ bạn đang cố đẩy tới sẽ tự thông khi bạn buông tay một lúc."},{"ma":"major-13","bo":"Ẩn Chính","so":13,"tenVi":"Cái Chết","tenEn":"Death","tuKhoa":"Kết thúc, lột xác, dọn chỗ","yNghiaXuoi":"Bộ xương cưỡi ngựa trắng đi qua, vua ngã xuống, trẻ con thì đưa hoa. Phía xa mặt trời mọc giữa hai cột. Một chuyện trong đời bạn đã hết vai trò của nó. Rất hiếm khi lá này ứng vào chết chóc. Nó ứng vào việc dọn chỗ cho thứ sắp tới.","yNghiaNguoc":"Đoàn người chắn ngang đường ngựa đi. Bạn níu một thứ đã xong, sợ thay đổi tới mức thà chịu đựng cái cũ.","tinhCam":"Một mối quan hệ tới hồi kết, hoặc đổi hẳn về bản chất. Níu lại chỉ thêm mệt.","congViec":"Nghỉ việc, đổi nghề, đóng một mảng kinh doanh. Sự kết thúc này là cần thiết.","loiKhuyen":"Đừng giữ lại thứ đã hết. Chỗ trống mới là thứ bạn đang cần."},{"ma":"major-14","bo":"Ẩn Chính","so":14,"tenVi":"Tiết Độ","tenEn":"Temperance","tuKhoa":"Cân bằng, pha trộn, vừa đủ","yNghiaXuoi":"Thiên thần rót nước qua lại giữa hai cái cốc, một chân đặt trên bờ một chân dưới nước, mà không đổ ra ngoài giọt nào. Việc bạn đang làm cần đúng liều lượng. Dồn quá hay buông quá đều hỏng như nhau.","yNghiaNguoc":"Nước tràn ra ngoài. Bạn làm gì cũng quá tay, nóng vội muốn có ngay kết quả. Hoặc đang sống lệch hẳn về một phía và cơ thể bắt đầu lên tiếng.","tinhCam":"Hai người đang học cách dung hoà khác biệt. Kiên nhẫn sẽ có kết quả.","congViec":"Phối hợp nhiều nguồn lực và nhiều người. Từ tốn mà chắc thì hơn làm gấp.","loiKhuyen":"Đi chậm một chút, nhưng đi đều. Lần này về đích theo kiểu đó."},{"ma":"major-15","bo":"Ẩn Chính","so":15,"tenVi":"Ác Quỷ","tenEn":"The Devil","tuKhoa":"Ràng buộc, cám dỗ, thói quen xấu","yNghiaXuoi":"Dưới chân con quỷ, một đôi nam nữ bị xích vào bệ đá. Nhìn kỹ thì vòng xích rộng hơn cổ họ nhiều, chỉ cần cúi đầu là tuột ra, nhưng họ không cúi. Có thứ đang giữ chân bạn mà chính bạn để nó giữ, chẳng hạn một khoản nợ, một thói quen, hay một mối quan hệ biết là không ổn.","yNghiaNguoc":"Có người bắt đầu cúi đầu. Bạn nhìn ra thứ đang trói mình và muốn gỡ, dù chặng đầu còn chật vật.","tinhCam":"Nặng về chiếm hữu hoặc ham muốn, thiếu tự do. Nhìn cho rõ thứ đang trói mình.","congViec":"Bị buộc vào công việc hoặc khoản tiền không cho bạn lối ra. Thoát được, chỉ là đang ngại.","loiKhuyen":"Cái xích ấy không khoá. Bạn chỉ chưa muốn gỡ."},{"ma":"major-16","bo":"Ẩn Chính","so":16,"tenVi":"Tòa Tháp","tenEn":"The Tower","tuKhoa":"Đổ vỡ đột ngột, vỡ mộng, làm lại","yNghiaXuoi":"Sét đánh trúng đỉnh tháp, vương miện văng ra, hai người rơi xuống. Một thứ bạn tưởng vững sắp sụp rất nhanh, nhanh tới mức không kịp chuẩn bị. Đau, nhưng thứ sụp xuống thường là thứ xây trên nền sai từ đầu.","yNghiaNguoc":"Tháp lung lay mà chưa sập. Bạn tránh được một cú lớn, hoặc đang gồng đỡ thứ đằng nào cũng đổ. Kéo dài chỉ làm cú ngã sau này nặng hơn.","tinhCam":"Một sự thật bất ngờ lật hết mọi chuyện. Chia tay, hoặc vỡ lẽ về nhau.","congViec":"Mất việc, dự án gãy, kế hoạch đổ. Không cứu được thì chuẩn bị dựng lại.","loiKhuyen":"Cái đổ hôm nay là cái lẽ ra phải đổ từ lâu."},{"ma":"major-17","bo":"Ẩn Chính","so":17,"tenVi":"Ngôi Sao","tenEn":"The Star","tuKhoa":"Hy vọng, chữa lành, niềm tin trở lại","yNghiaXuoi":"Trong bộ bài, lá này đứng ngay sau Tòa Tháp. Một người quỳ bên hồ, rót nước xuống đất và xuống nước, trên trời có tám ngôi sao. Giai đoạn khó đã qua và mọi thứ đang lành lại, tuy còn chậm.","yNghiaNguoc":"Nước vẫn rót nhưng người rót đã mỏi. Bạn mất niềm tin, thấy cố mãi cũng chẳng tới đâu. Vết thương cũ chưa liền mà đã tự trách mình vì còn đau.","tinhCam":"Vết thương cũ đang liền. Một người đến nhẹ nhàng và chân thành.","congViec":"Có hướng đi rõ ràng trở lại. Cứ theo đuổi cái mình thật lòng muốn.","loiKhuyen":"Giữ lấy hy vọng đó. Lần này nó có cơ sở."},{"ma":"major-18","bo":"Ẩn Chính","so":18,"tenVi":"Mặt Trăng","tenEn":"The Moon","tuKhoa":"Mơ hồ, lo sợ, điều giấu kín","yNghiaXuoi":"Con đường chạy giữa hai cái tháp, chó và sói cùng tru lên mặt trăng, một con tôm bò lên từ mặt nước. Dưới thứ ánh sáng này cái gì cũng trông khác đi. Bạn đang nhìn sự việc qua nỗi sợ của mình, nên thứ bạn thấy chưa chắc là thứ có thật.","yNghiaNguoc":"Trời bắt đầu sáng. Sương tan dần, và nỗi sợ bấy lâu hoá ra không to như bạn tưởng.","tinhCam":"Nghi ngờ, hiểu lầm, có chuyện giấu nhau. Hỏi thẳng thay vì tự suy diễn.","congViec":"Thông tin chưa đầy đủ hoặc không thật. Kiểm lại trước khi tin.","loiKhuyen":"Đừng quyết trong bóng tối. Chờ trời sáng rồi hẵng đi."},{"ma":"major-19","bo":"Ẩn Chính","so":19,"tenVi":"Mặt Trời","tenEn":"The Sun","tuKhoa":"Rõ ràng, vui vẻ, thành công","yNghiaXuoi":"Đứa trẻ cưỡi ngựa trắng dưới mặt trời, sau lưng là tường hoa hướng dương, và cả bức tranh không có lấy một cái bóng. Việc bạn đang chờ sẽ thuận. Không có gì phải ngờ vực ở lá này.","yNghiaNguoc":"Mặt trời vẫn đó nhưng có mây ngang qua. Niềm vui bị che bớt, hoặc thành công tới mà trong lòng vẫn thấy trống. Cũng có khi lạc quan quá nên bỏ qua chi tiết đáng lo.","tinhCam":"Ấm áp và công khai. Tin vui về cưới hỏi hoặc con cái.","congViec":"Thành quả tới và được nhìn nhận. Dự án chạy tốt.","loiKhuyen":"Nhận lấy điều tốt đang đến mà không cần thấy áy náy."},{"ma":"major-20","bo":"Ẩn Chính","so":20,"tenVi":"Phán Xét","tenEn":"Judgement","tuKhoa":"Thức tỉnh, tổng kết, gọi mời","yNghiaXuoi":"Tiếng kèn vang lên, người ngồi dậy từ quan tài và giơ hai tay. Không ai bị lôi dậy cả, họ nghe thấy rồi tự đứng lên. Đã tới lúc bạn nhìn lại cả chặng vừa qua và quyết định sẽ sống tiếp thế nào.","yNghiaNguoc":"Kèn thổi mà không ai nhúc nhích. Bạn tự trách mãi về chuyện cũ, hoặc nghe thấy lời gọi nhưng làm ngơ. Có khi là phán xét người khác quá nặng.","tinhCam":"Cơ hội nối lại, hoặc nói cho xong chuyện cũ. Tha thứ được thì nhẹ cả hai.","congViec":"Nhìn lại cả quá trình để chọn hướng mới. Một lời mời quan trọng có thể tới.","loiKhuyen":"Đối diện chuyện cũ một lần cho dứt, rồi bước tiếp."},{"ma":"major-21","bo":"Ẩn Chính","so":21,"tenVi":"Thế Giới","tenEn":"The World","tuKhoa":"Trọn vẹn, hoàn tất, mở rộng","yNghiaXuoi":"Người múa trong vòng nguyệt quế, bốn góc là bốn sinh vật canh giữ. Một vòng đã đi hết và khép lại đúng chỗ nó bắt đầu, chỉ khác là bạn của hôm nay không còn là bạn lúc xuất phát. Việc lớn bạn theo đuổi bấy lâu đang tới hồi hoàn tất.","yNghiaNguoc":"Vòng nguyệt quế hở một chỗ. Sắp xong mà mãi chưa xong, còn một mắt xích chưa gỡ. Hoặc đã xong rồi nhưng bạn không cho phép mình dừng lại để thấy là đủ.","tinhCam":"Chín muồi, hai người thuộc về nhau. Hoặc một chuyện cũ khép lại thanh thản.","congViec":"Hoàn thành một chặng lớn. Có thể liên quan tới đi xa hoặc làm việc với nước ngoài.","loiKhuyen":"Ăn mừng cho chặng đã xong, rồi hãy nghĩ tới chặng sau."},{"ma":"cups-01","bo":"Cốc","so":1,"tenVi":"Át Cốc","tenEn":"Ace of Cups","tuKhoa":"Rung động mới, lòng mở ra","yNghiaXuoi":"Một bàn tay từ mây đưa ra chiếc cốc tràn nước, con chim bồ câu cắm xuống. Nước chảy ra năm dòng mà cốc vẫn đầy. Một dòng cảm xúc mới đang mở trong bạn, có thể là tình cảm, cũng có thể là niềm vui sống trở lại sau một quãng nguội lạnh.","yNghiaNguoc":"Cốc nghiêng, nước đổ hết ra ngoài. Bạn dồn nén cảm xúc không nói ra được, hoặc một tình cảm vừa chớm đã tắt vì chính bạn đóng cửa lại.","tinhCam":"Có người mới xuất hiện, hoặc tình cũ ấm trở lại. Cứ để lòng mình mở ra.","congViec":"Công việc mang lại cảm hứng trở lại. Hợp với nghề cần sự đồng cảm.","loiKhuyen":"Đừng sợ rung động. Cứ để nó đến rồi hẵng tính."},{"ma":"cups-02","bo":"Cốc","so":2,"tenVi":"Hai Cốc","tenEn":"Two of Cups","tuKhoa":"Đôi bên, đồng lòng, kết giao","yNghiaXuoi":"Hai người trao cốc cho nhau, phía trên là cây trượng có hai con rắn quấn và đầu sư tử. Họ đứng ngang hàng, không ai cúi đầu. Bạn và ai đó đang hợp nhau thật sự. Tình yêu, bạn bè hay làm ăn đều có thể.","yNghiaNguoc":"Hai cái cốc không chạm nhau. Một bên cho nhiều hơn hẳn, hoặc hiểu lầm đang đẩy hai người xa dần.","tinhCam":"Hoà hợp, có thể tiến tới gắn bó lâu dài.","congViec":"Hợp tác thuận lợi. Tìm được người cùng chí hướng.","loiKhuyen":"Quan hệ chỉ đứng vững khi hai bên cùng giữ."},{"ma":"cups-03","bo":"Cốc","so":3,"tenVi":"Ba Cốc","tenEn":"Three of Cups","tuKhoa":"Sum vầy, ăn mừng, bạn bè","yNghiaXuoi":"Ba cô gái giơ cốc lên trời giữa mùa quả chín dưới chân. Có chuyện đáng mừng và bạn không mừng một mình. Gọi người thân bạn bè lại đi.","yNghiaNguoc":"Tiệc tan mà người thì mệt. Vui quá đà, hoặc bạn bè hoá ra không thật lòng. Cũng có khi bạn thấy lạc lõng ngay giữa đám đông.","tinhCam":"Được bạn bè ủng hộ. Có tin vui cần ăn mừng.","congViec":"Làm việc nhóm ăn ý. Công sức tập thể được ghi nhận.","loiKhuyen":"Gọi bạn bè lại. Niềm vui chia ra thì nhiều hơn."},{"ma":"cups-04","bo":"Cốc","so":4,"tenVi":"Bốn Cốc","tenEn":"Four of Cups","tuKhoa":"Chán chường, thờ ơ, bỏ lỡ","yNghiaXuoi":"Chàng trai ngồi khoanh tay dưới gốc cây, trước mặt có ba cái cốc mà không buồn nhìn, trong khi một bàn tay từ mây chìa ra cái cốc thứ tư. Có thứ tốt đang đưa tới mà bạn không thấy, vì đang mải chán.","yNghiaNguoc":"Chàng trai ngẩng lên. Bạn bắt đầu tỉnh lại và nhận ra thứ mình đã bỏ qua.","tinhCam":"Đang nguội lạnh, hoặc không nhận ra người tốt ngay bên cạnh.","congViec":"Chán việc, làm cho xong. Hãy xem thứ mình thật sự muốn là gì.","loiKhuyen":"Ngẩng lên nhìn quanh. Thứ bạn tìm có thể đang ở ngay đó."},{"ma":"cups-05","bo":"Cốc","so":5,"tenVi":"Năm Cốc","tenEn":"Five of Cups","tuKhoa":"Tiếc nuối, mất mát, ngoảnh lại","yNghiaXuoi":"Người khoác áo đen cúi nhìn ba cái cốc đổ, mà sau lưng vẫn còn hai cái đứng nguyên, phía xa có cây cầu dẫn về nhà. Bạn đang tiếc một thứ đã mất tới mức không thấy phần còn lại.","yNghiaNguoc":"Người ấy quay lại nhìn hai cái cốc còn đứng. Bạn bắt đầu nguôi và chấp nhận được chuyện đã qua.","tinhCam":"Còn vương vấn chuyện cũ nên chưa mở lòng cho chuyện mới.","congViec":"Một thất bại còn ám ảnh. Rút bài học rồi đi tiếp.","loiKhuyen":"Đừng chỉ đếm thứ đã mất. Quay lại nhìn thứ còn nguyên."},{"ma":"cups-06","bo":"Cốc","so":6,"tenVi":"Sáu Cốc","tenEn":"Six of Cups","tuKhoa":"Kỷ niệm, người cũ, trong trẻo","yNghiaXuoi":"Một đứa trẻ đưa cho đứa khác chiếc cốc cắm đầy hoa, trong sân một ngôi nhà cũ. Quá khứ đang quay lại một cách hiền lành, có thể là người cũ, chốn cũ, hoặc một ký ức tuổi nhỏ.","yNghiaNguoc":"Bạn sống trong kỷ niệm mà quên hiện tại, hoặc nhớ về quá khứ đẹp hơn thực tế nó từng có.","tinhCam":"Người cũ quay lại, hoặc tình cảm nảy từ một quan hệ quen lâu năm.","congViec":"Một cơ hội đến từ quan hệ cũ. Có thể quay lại nơi từng làm.","loiKhuyen":"Nhớ thì cứ nhớ, nhưng đừng dọn vào đó ở."},{"ma":"cups-07","bo":"Cốc","so":7,"tenVi":"Bảy Cốc","tenEn":"Seven of Cups","tuKhoa":"Nhiều lựa chọn, ảo tưởng, hoa mắt","yNghiaXuoi":"Bảy cái cốc hiện ra trong mây, mỗi cái đựng một thứ, có cốc đựng châu báu, có cốc đựng con rắn. Người đứng nhìn chỉ thấy bóng mình. Trước mặt bạn nhiều hướng quá nên cuối cùng chẳng chọn được hướng nào, mà có thứ chỉ đẹp ở vẻ ngoài.","yNghiaNguoc":"Mây tan, các cốc rõ dần. Bạn nhìn ra đâu là thật đâu là mơ, và đã chọn được một hướng.","tinhCam":"Đang phân vân giữa nhiều người, hoặc yêu một hình ảnh mình tự vẽ ra.","congViec":"Nhiều cơ hội nhưng chưa cái nào chắc. Đừng ôm hết.","loiKhuyen":"Bỏ bớt đi. Chọn một thứ và làm cho tới."},{"ma":"cups-08","bo":"Cốc","so":8,"tenVi":"Tám Cốc","tenEn":"Eight of Cups","tuKhoa":"Rời đi, buông, tìm thứ khác","yNghiaXuoi":"Người chống gậy quay lưng bỏ đi dưới trăng, để lại tám cái cốc xếp ngay ngắn, không đổ cái nào. Bạn rời một thứ vẫn còn tốt, vì biết nó không cho mình điều mình cần. Ra đi kiểu này là tỉnh táo, chứ không phải bỏ cuộc.","yNghiaNguoc":"Bạn dùng dằng mãi không dứt được, biết nên đi mà cứ ở lại. Hoặc vừa quay lại thứ mình đã bỏ.","tinhCam":"Muốn kết thúc một mối quan hệ đã cạn. Đi hay ở đều cần dứt khoát.","congViec":"Rời một công việc ổn định để tìm thứ có ý nghĩa hơn.","loiKhuyen":"Có những thứ tốt mà vẫn phải bỏ lại, vì nó không dành cho bạn."},{"ma":"cups-09","bo":"Cốc","so":9,"tenVi":"Chín Cốc","tenEn":"Nine of Cups","tuKhoa":"Toại nguyện, đủ đầy, ước thành","yNghiaXuoi":"Người đàn ông ngồi khoanh tay, mặt mãn nguyện, sau lưng là chín cái cốc xếp trên bệ phủ vải. Điều bạn mong đang thành. Người ta hay gọi đây là lá của điều ước.","yNghiaNguoc":"Được cái mình muốn rồi mà vẫn thấy thiếu. Hoặc mong cầu đặt sai chỗ nên đạt được cũng không vui.","tinhCam":"Hạnh phúc trong tầm tay. Hãy trân trọng cái đang có.","congViec":"Thành quả tới, xứng đáng với công sức. Tài chính khá lên.","loiKhuyen":"Cho phép mình vui. Bạn đã trả giá đủ rồi."},{"ma":"cups-10","bo":"Cốc","so":10,"tenVi":"Mười Cốc","tenEn":"Ten of Cups","tuKhoa":"Sum họp, hạnh phúc, mái ấm","yNghiaXuoi":"Hai vợ chồng giang tay nhìn cầu vồng mười cái cốc, hai đứa trẻ nắm tay nhảy bên cạnh, xa xa là ngôi nhà. Thứ bạn đang có hoặc sắp có là sự yên ổn bền lâu, không phải niềm vui rực rỡ nhất thời.","yNghiaNguoc":"Cầu vồng mờ đi. Gia đình lục đục, hoặc bề ngoài êm ấm mà bên trong không phải vậy.","tinhCam":"Đi tới bền vững, hướng gia đình. Tin vui về cưới hỏi.","congViec":"Công việc và đời sống riêng cân được với nhau.","loiKhuyen":"Hạnh phúc thật thường trông rất bình thường."},{"ma":"cups-11","bo":"Cốc","so":11,"tenVi":"Tiểu Đồng Cốc","tenEn":"Page of Cups","tuKhoa":"Ngây thơ, tin mới, cảm hứng","yNghiaXuoi":"Cậu bé cầm cốc, trong cốc có con cá ngoi lên nhìn cậu, và cậu không hề ngạc nhiên. Một tin nhắn, một lời tỏ bày hoặc một ý tưởng sắp đến với bạn, đến từ cảm xúc chứ không từ tính toán.","yNghiaNguoc":"Con cá biến mất. Dỗi hờn trẻ con, cảm xúc thất thường, hoặc một lời hứa nói ra rồi không giữ.","tinhCam":"Có người bày tỏ tình cảm, nhẹ nhàng và chân thành.","congViec":"Ý tưởng mới đáng nuôi. Đừng vội chê nó còn non.","loiKhuyen":"Giữ lấy sự hồn nhiên đó, nó không làm bạn yếu đi đâu."},{"ma":"cups-12","bo":"Cốc","so":12,"tenVi":"Hiệp Sĩ Cốc","tenEn":"Knight of Cups","tuKhoa":"Lãng mạn, theo đuổi, lời mời","yNghiaXuoi":"Hiệp sĩ cưỡi ngựa trắng đi thong thả, hai tay nâng cốc như đang mang tặng ai. Mũ có đôi cánh nhỏ. Một người đến với lời đề nghị đẹp đẽ, hoặc chính bạn đang đi theo tiếng gọi của con tim.","yNghiaNguoc":"Cốc rỗng mà vẫn giơ ra. Lời ngọt không có gì phía sau, hoặc bạn mơ mộng tới mức xa rời thực tế.","tinhCam":"Có người theo đuổi rất khéo. Xem kỹ họ có thật lòng không.","congViec":"Một lời mời hấp dẫn. Kiểm tra phần thực tế trước khi gật.","loiKhuyen":"Nghe con tim thì được, nhưng đừng bỏ cái đầu ở nhà."},{"ma":"cups-13","bo":"Cốc","so":13,"tenVi":"Hoàng Hậu Cốc","tenEn":"Queen of Cups","tuKhoa":"Thấu hiểu, dịu dàng, trực giác","yNghiaXuoi":"Bà ngồi bên mép nước, nhìn chăm chú vào chiếc cốc có nắp trong tay, cái cốc duy nhất đóng kín trong cả bộ. Người này hiểu lòng người khác mà không cần được kể. Có thể là bạn, có thể là người đang ở cạnh bạn.","yNghiaNguoc":"Nước tràn lên tận chân ngai. Chìm trong cảm xúc của người khác tới mức mất mình, hoặc dùng sự yếu mềm để níu giữ ai đó.","tinhCam":"Một người bao dung và tinh tế. Hãy nghe nhau nhiều hơn.","congViec":"Hợp với việc chăm sóc, tư vấn, làm cầu nối giữa người với người.","loiKhuyen":"Thương người thì tốt, nhưng nhớ chừa phần cho mình."},{"ma":"cups-14","bo":"Cốc","so":14,"tenVi":"Vua Cốc","tenEn":"King of Cups","tuKhoa":"Điềm tĩnh, chín chắn, làm chủ cảm xúc","yNghiaXuoi":"Ngai của ông trôi trên mặt biển động, cá nhảy một bên, thuyền nghiêng một bên, mà ông vẫn ngồi yên. Người này nhiều cảm xúc nhưng không để cảm xúc điều khiển. Việc trước mặt cần đúng cái đầu lạnh và tấm lòng ấm cùng lúc.","yNghiaNguoc":"Sóng đánh lên tới ngai. Kìm nén tới mức nguội lạnh, hoặc bề ngoài bình thản mà bên trong đang rối. Cũng có thể là người thao túng cảm xúc người khác.","tinhCam":"Một người chững chạc, đáng tin. Giải quyết mâu thuẫn bằng bình tĩnh.","congViec":"Được tin tưởng giao việc cần khéo léo với con người.","loiKhuyen":"Cảm xúc là thứ để hiểu, không phải thứ để nghe lời."},{"ma":"wands-01","bo":"Gậy","so":1,"tenVi":"Át Gậy","tenEn":"Ace of Wands","tuKhoa":"Hứng khởi, bắt đầu, đốm lửa","yNghiaXuoi":"Một bàn tay từ mây nắm cây gậy còn đâm chồi, mấy chiếc lá rụng lả tả quanh đó. Bạn vừa có một ý tưởng hoặc cơ hội làm thứ mình thật sự muốn, và sức bật đang lên nên dùng ngay.","yNghiaNguoc":"Gậy tuột khỏi tay. Hứng lên rồi tắt, khởi động mãi không xong. Hoặc cơ hội tới mà bạn chần chừ để nó nguội.","tinhCam":"Sức hút mạnh, một khởi đầu đầy lửa. Hãy chủ động.","congViec":"Thời điểm tốt để bắt đầu dự án hoặc mở việc riêng.","loiKhuyen":"Đốm lửa này chỉ cháy nếu bạn thổi ngay bây giờ."},{"ma":"wands-02","bo":"Gậy","so":2,"tenVi":"Hai Gậy","tenEn":"Two of Wands","tuKhoa":"Nhìn xa, lên kế hoạch, chọn hướng","yNghiaXuoi":"Người đàn ông đứng trên tường thành, một tay cầm gậy một tay ôm quả địa cầu, nhìn ra biển. Ông đã có chỗ đứng rồi mà vẫn nhìn ra xa. Bạn đang cân nhắc giữa ở yên chỗ quen và bước ra chỗ rộng hơn.","yNghiaNguoc":"Quả địa cầu đặt xuống. Bạn sợ rời vùng an toàn, hoặc vẽ kế hoạch hoài mà không thực hiện.","tinhCam":"Cân nhắc có nên tiến xa hơn với người này không.","congViec":"Đang tính chuyện mở rộng. Chuẩn bị kỹ rồi hẵng đi.","loiKhuyen":"Có tầm nhìn là tốt, nhưng phải có ngày khởi hành."},{"ma":"wands-03","bo":"Gậy","so":3,"tenVi":"Ba Gậy","tenEn":"Three of Wands","tuKhoa":"Chờ kết quả, mở rộng, đường dài","yNghiaXuoi":"Người đứng trên mỏm cao quay lưng lại, nhìn những con thuyền ngoài khơi. Thứ bạn gieo đã ra khơi và đang trên đường về. Việc còn lại là chờ cho đúng lúc.","yNghiaNguoc":"Thuyền chưa thấy đâu. Chậm trễ, kế hoạch không như dự tính, hoặc tầm nhìn còn hẹp hơn bạn tưởng.","tinhCam":"Cần thời gian, có thể phải xa nhau một quãng.","congViec":"Hợp tác mở rộng, làm ăn với nơi xa. Kết quả sắp về.","loiKhuyen":"Bạn đã làm phần của mình. Giờ là phần của thời gian."},{"ma":"wands-04","bo":"Gậy","so":4,"tenVi":"Bốn Gậy","tenEn":"Four of Wands","tuKhoa":"Ổn định, mừng vui, về nhà","yNghiaXuoi":"Bốn cây gậy dựng thành cổng kết hoa, hai người giơ bó hoa đón phía sau, xa xa là toà thành. Một chặng đã xong và đáng để ăn mừng. Bạn đang có cảm giác vững chãi, có chốn thuộc về.","yNghiaNguoc":"Cổng hoa dỡ xuống. Niềm vui bị hoãn, hoặc không khí gia đình đang có chuyện. Cũng có khi bạn chưa tìm được chỗ cho mình.","tinhCam":"Tin vui về đính hôn, cưới hỏi, dọn về sống chung.","congViec":"Một chặng hoàn tất. Nền móng đã chắc để đi tiếp.","loiKhuyen":"Dừng lại mừng một chút đã, rồi hẵng chạy tiếp."},{"ma":"wands-05","bo":"Gậy","so":5,"tenVi":"Năm Gậy","tenEn":"Five of Wands","tuKhoa":"Va chạm, cạnh tranh, lộn xộn","yNghiaXuoi":"Năm người vung gậy loạn xạ, nhưng nhìn kỹ thì không ai đánh trúng ai. Xô xát kiểu này sinh ra vì nhiều người cùng muốn một thứ, không phải vì thù hằn. Bạn đang ở giữa một chỗ ồn ào mà chưa ai chịu ai.","yNghiaNguoc":"Gậy hạ xuống. Xung đột lắng, hoặc mâu thuẫn bị nén lại chứ chưa giải quyết.","tinhCam":"Cãi vặt liên tục vì những chuyện nhỏ. Cần một người chịu nhường trước.","congViec":"Cạnh tranh gay gắt. Giữ vững phần mình, đừng sa vào tranh cãi.","loiKhuyen":"Không phải cuộc tranh nào cũng đáng để bạn nhảy vào."},{"ma":"wands-06","bo":"Gậy","so":6,"tenVi":"Sáu Gậy","tenEn":"Six of Wands","tuKhoa":"Thắng lợi, được công nhận, ngẩng đầu","yNghiaXuoi":"Người cưỡi ngựa đội vòng nguyệt quế đi giữa đám đông, gậy của ông cũng có vòng nguyệt quế buộc trên đầu. Bạn được ghi nhận sau một chặng cố gắng, và lần này có người nhìn thấy.","yNghiaNguoc":"Vòng nguyệt quế rơi. Công sức không ai biết tới, hoặc thắng rồi sinh kiêu. Cũng có khi bạn quá cần lời khen của người khác.","tinhCam":"Được người kia coi trọng. Mối quan hệ khởi sắc.","congViec":"Thành tích được ghi nhận, có thể được thăng tiến.","loiKhuyen":"Nhận lời khen cho đàng hoàng, rồi tiếp tục làm việc."},{"ma":"wands-07","bo":"Gậy","so":7,"tenVi":"Bảy Gậy","tenEn":"Seven of Wands","tuKhoa":"Giữ vững, phòng thủ, đứng về phía mình","yNghiaXuoi":"Một người đứng trên gò cao chống đỡ sáu cây gậy chĩa lên từ phía dưới. Ông đi hai chiếc giày khác nhau, nghĩa là bị tấn công bất ngờ. Bạn đang phải bảo vệ điều mình tin trước nhiều người, nhưng bạn đứng ở chỗ cao hơn họ.","yNghiaNguoc":"Người ấy bước xuống khỏi gò. Bạn đuối sức và muốn buông, hoặc phòng thủ cả những chỗ chẳng ai tấn công.","tinhCam":"Phải bảo vệ mối quan hệ trước lời ra tiếng vào.","congViec":"Bị cạnh tranh hoặc chất vấn. Giữ nguyên quan điểm nếu bạn đúng.","loiKhuyen":"Bạn đang đứng chỗ cao hơn họ. Đừng bước xuống để cãi nhau."},{"ma":"wands-08","bo":"Gậy","so":8,"tenVi":"Tám Gậy","tenEn":"Eight of Wands","tuKhoa":"Nhanh, dồn dập, tin tới","yNghiaXuoi":"Tám cây gậy bay ngang trời, không có người nào trong tranh. Mọi thứ đang tăng tốc. Tin nhắn, cuộc gọi và sự việc kéo đến cùng lúc, và chúng chuyển rất nhanh.","yNghiaNguoc":"Gậy rơi lả tả. Trì trệ, chờ mãi không thấy hồi âm. Hoặc bạn vội quá nên làm hỏng việc.","tinhCam":"Tiến triển nhanh. Có tin từ người bạn đang chờ.","congViec":"Việc dồn tới một lúc. Xử lý theo thứ tự, đừng ôm hết.","loiKhuyen":"Đang đà thì đi, đừng dừng lại nghĩ quá lâu."},{"ma":"wands-09","bo":"Gậy","so":9,"tenVi":"Chín Gậy","tenEn":"Nine of Wands","tuKhoa":"Mệt mà chưa xong, cảnh giác, gắng nốt","yNghiaXuoi":"Người đàn ông băng đầu, tựa vào một cây gậy, tám cây còn lại dựng sau lưng như hàng rào. Ông mang thương tích nhưng vẫn đứng. Bạn đã qua nhiều chặng và chỉ còn một đoạn nữa.","yNghiaNguoc":"Hàng rào đổ. Bạn kiệt sức thật sự, hoặc đề phòng tới mức không cho ai lại gần.","tinhCam":"Vết thương cũ làm bạn khó tin người mới.","congViec":"Còn một chặng nữa là xong. Đừng bỏ lúc này.","loiKhuyen":"Bạn mệt, nhưng bạn chưa gục. Cố nốt đoạn này."},{"ma":"wands-10","bo":"Gậy","so":10,"tenVi":"Mười Gậy","tenEn":"Ten of Wands","tuKhoa":"Gánh nặng, ôm đồm, quá tải","yNghiaXuoi":"Người ôm mười cây gậy che hết tầm nhìn, lưng còng xuống, nhà còn ở phía xa. Bạn đang vác nhiều hơn sức mình. Câu đáng hỏi là trong đống đó có bao nhiêu thứ thật sự là của bạn.","yNghiaNguoc":"Gậy rơi xuống đất. Bạn bắt đầu bỏ bớt được, hoặc gục hẳn vì không chịu buông sớm hơn.","tinhCam":"Quan hệ thành nghĩa vụ nhiều hơn là niềm vui.","congViec":"Ôm quá nhiều việc. Giao bớt đi hoặc từ chối bớt.","loiKhuyen":"Đặt xuống vài thứ. Không ai bắt bạn vác hết."},{"ma":"wands-11","bo":"Gậy","so":11,"tenVi":"Tiểu Đồng Gậy","tenEn":"Page of Wands","tuKhoa":"Háo hức, khám phá, tin vui","yNghiaXuoi":"Cậu thiếu niên đứng giữa sa mạc, cầm cây gậy đang nảy mầm và ngắm nó chăm chú. Một tin tức hoặc cơ hội làm bạn phấn khích trở lại. Còn non nhưng đầy sức sống.","yNghiaNguoc":"Mầm trên gậy héo. Nhiệt tình nhất thời rồi bỏ dở giữa chừng. Hoặc tin đồn chưa kiểm chứng.","tinhCam":"Một người trẻ trung, vui vẻ xuất hiện. Giai đoạn tìm hiểu nhiều hứng khởi.","congViec":"Có cơ hội học thứ mới. Cứ thử, sai cũng không sao.","loiKhuyen":"Đừng để cái hứng này tắt trước khi bạn kịp làm gì."},{"ma":"wands-12","bo":"Gậy","so":12,"tenVi":"Hiệp Sĩ Gậy","tenEn":"Knight of Wands","tuKhoa":"Bốc đồng, lao tới, liều","yNghiaXuoi":"Ngựa chồm hai chân trước, hiệp sĩ ghì lấy, áo giáp vẽ đầy kỳ nhông. Người này đi trước nghĩ sau, nhiều năng lượng và có sức hút, nhưng ít kiên nhẫn với chi tiết.","yNghiaNguoc":"Ngựa hất ông xuống. Nóng vội gây hỏng việc, hứa rồi bỏ ngang. Hoặc mất hết động lực.","tinhCam":"Một người nồng nhiệt nhưng khó đoán. Vui thì rất vui, bền thì chưa chắc.","congViec":"Dám làm và làm nhanh, nhưng dễ sót. Cần người rà lại sau lưng.","loiKhuyen":"Nhiệt tình là vốn quý, miễn là bạn đi hết được đoạn đường."},{"ma":"wands-13","bo":"Gậy","so":13,"tenVi":"Hoàng Hậu Gậy","tenEn":"Queen of Wands","tuKhoa":"Tự tin, ấm áp, có sức hút","yNghiaXuoi":"Bà ngồi thẳng lưng, một tay cầm gậy một tay cầm hoa hướng dương, con mèo đen ngồi dưới chân nhìn thẳng ra ngoài. Người này biết mình là ai và không cần ai xác nhận. Sức hút của họ đến tự nhiên chứ không phải cố.","yNghiaNguoc":"Hoa hướng dương rũ xuống. Tự tin bị lung lay, hoặc sinh ghen tuông và hơn thua. Cũng có khi là gồng lên cho trông có vẻ ổn.","tinhCam":"Một người nồng nhiệt và thẳng thắn. Cứ là chính mình.","congViec":"Dẫn dắt được người khác nhờ khí chất chứ không nhờ chức vụ.","loiKhuyen":"Bạn không cần ai gật đầu thì mới được là mình."},{"ma":"wands-14","bo":"Gậy","so":14,"tenVi":"Vua Gậy","tenEn":"King of Wands","tuKhoa":"Thủ lĩnh, tầm nhìn, dám quyết","yNghiaXuoi":"Ông ngồi hơi nghiêng như sắp đứng dậy, gậy chống xuống đất, kỳ nhông nhỏ bên chân ngậm đuôi mình. Người này vạch ra hướng đi rồi kéo người khác theo. Việc trước mặt cần một người nhìn xa và dám làm tới.","yNghiaNguoc":"Ông ngồi lún xuống ngai. Độc đoán, không nghe ai. Hoặc có tầm nhìn mà thiếu người theo vì cách cư xử.","tinhCam":"Một người mạnh mẽ, quyết đoán. Cần tôn trọng lẫn nhau.","congViec":"Thích hợp cầm trịch một việc lớn. Quyết rồi thì chịu trách nhiệm.","loiKhuyen":"Dẫn đường thì phải quay lại xem có ai còn theo kịp không."},{"ma":"swords-01","bo":"Kiếm","so":1,"tenVi":"Át Kiếm","tenEn":"Ace of Swords","tuKhoa":"Sáng tỏ, sự thật, quyết định","yNghiaXuoi":"Bàn tay từ mây nắm thanh kiếm dựng thẳng, mũi kiếm xuyên qua vòng vương miện có cành ô liu và lá cọ. Bạn vừa nhìn ra vấn đề đúng như nó là, và có đủ can đảm gọi tên nó. Giờ là lúc cắt cho dứt.","yNghiaNguoc":"Kiếm chúc xuống. Nghĩ mãi không thông, hoặc dùng sự thật như một nhát dao. Cũng có khi quyết định đưa ra dựa trên thông tin sai.","tinhCam":"Cần một cuộc nói chuyện thẳng thắn. Nói rõ còn hơn đoán mò.","congViec":"Tìm ra hướng giải quyết. Thời điểm tốt để ký kết hoặc chốt phương án.","loiKhuyen":"Nói thật, nhưng chọn cách nói cho người ta nghe được."},{"ma":"swords-02","bo":"Kiếm","so":2,"tenVi":"Hai Kiếm","tenEn":"Two of Swords","tuKhoa":"Bế tắc, né tránh, không chọn","yNghiaXuoi":"Người phụ nữ bịt mắt, hai tay bắt chéo ôm hai thanh kiếm, sau lưng là biển có đá ngầm. Bạn đang bịt mắt trước một chuyện phải quyết, vì hai hướng đều có lý nên đứng yên trông an toàn nhất.","yNghiaNguoc":"Khăn bịt mắt được tháo ra, bạn buộc phải nhìn. Hoặc bế tắc kéo dài tới mức hoàn cảnh quyết thay bạn.","tinhCam":"Lấp lửng, không rõ ràng với nhau. Cần một câu trả lời dứt khoát.","congViec":"Hoãn quyết định chỉ làm vấn đề lớn hơn. Tìm thêm thông tin rồi chọn.","loiKhuyen":"Không chọn cũng là một lựa chọn, và thường là lựa chọn tệ nhất."},{"ma":"swords-03","bo":"Kiếm","so":3,"tenVi":"Ba Kiếm","tenEn":"Three of Swords","tuKhoa":"Tổn thương, đau lòng, sự thật phũ","yNghiaXuoi":"Ba thanh kiếm xuyên qua một trái tim, trên nền trời mưa. Không có người nào trong tranh, chỉ có nỗi đau trần trụi. Có chuyện làm bạn đau, và nó đau vì nó thật.","yNghiaNguoc":"Kiếm bắt đầu rút ra. Vết thương đang lành, cơn đau nhạt dần. Hoặc bạn cố nén thay vì cho nó chảy ra.","tinhCam":"Chia tay, phản bội, hoặc một sự thật làm sụp niềm tin.","congViec":"Tin xấu hoặc lời phê bình nặng. Nhận rồi đi tiếp.","loiKhuyen":"Đau thì cứ đau cho hết. Nén lại chỉ làm nó ở lâu hơn."},{"ma":"swords-04","bo":"Kiếm","so":4,"tenVi":"Bốn Kiếm","tenEn":"Four of Swords","tuKhoa":"Nghỉ ngơi, tạm dừng, hồi sức","yNghiaXuoi":"Hiệp sĩ nằm trên bia đá trong nhà thờ, ba thanh kiếm treo trên tường và một thanh nằm dưới lưng. Ông không chết, ông đang nghỉ. Bạn cũng nên nằm xuống thay vì cố thêm.","yNghiaNguoc":"Hiệp sĩ ngồi dậy. Nghỉ đủ rồi, đến lúc quay lại. Hoặc ngược lại, kiệt sức mà vẫn không cho mình dừng.","tinhCam":"Cần khoảng lặng cho cả hai. Đừng bàn chuyện lớn lúc đang mệt.","congViec":"Tạm gác việc lại. Làm tiếp trong trạng thái này chỉ sinh lỗi.","loiKhuyen":"Nghỉ không phải là bỏ cuộc. Đó là một phần của việc."},{"ma":"swords-05","bo":"Kiếm","so":5,"tenVi":"Năm Kiếm","tenEn":"Five of Swords","tuKhoa":"Thắng mà thua, cãi vã, ích kỷ","yNghiaXuoi":"Người đàn ông thu ba thanh kiếm về mình và cười, hai người kia quay lưng bỏ đi. Bạn có thể thắng cuộc tranh này, nhưng cái giá là mối quan hệ. Câu đáng hỏi là thắng xong rồi còn lại gì.","yNghiaNguoc":"Kiếm rơi xuống đất. Bạn sẵn sàng làm hoà, hoặc còn cay cú mãi về một chuyện đã qua lâu.","tinhCam":"Cãi nhau tới mức tổn thương nhau. Ai cũng muốn mình đúng.","congViec":"Cạnh tranh không đẹp. Cân nhắc có đáng đánh đổi không.","loiKhuyen":"Có những cuộc thắng làm bạn nghèo đi."},{"ma":"swords-06","bo":"Kiếm","so":6,"tenVi":"Sáu Kiếm","tenEn":"Six of Swords","tuKhoa":"Rời đi, chuyển tiếp, sang bờ khác","yNghiaXuoi":"Người lái đò chở một phụ nữ và đứa trẻ, sáu thanh kiếm cắm trên thuyền. Nước bên này động, bên kia phẳng lặng. Bạn đang rời khỏi một quãng khó để sang chỗ yên hơn, chưa hết buồn nhưng hướng đi đã đúng.","yNghiaNguoc":"Thuyền mắc cạn. Bạn muốn đi mà chưa đi được, hoặc mang theo cả gánh cũ sang chỗ mới.","tinhCam":"Bước qua một chuyện cũ. Nhẹ dần theo thời gian.","congViec":"Chuyển việc, chuyển nơi ở. Thay đổi này là cần thiết.","loiKhuyen":"Đi thì đi, nhưng đừng vác hết hành lý cũ theo."},{"ma":"swords-07","bo":"Kiếm","so":7,"tenVi":"Bảy Kiếm","tenEn":"Seven of Swords","tuKhoa":"Giấu giếm, mánh khoé, không thật thà","yNghiaXuoi":"Người đàn ông ôm năm thanh kiếm rón rén rời khỏi doanh trại, còn hai thanh cắm lại phía sau. Ông ngoái đầu nhìn mà vẫn bước. Có ai đó đang không nói hết, và cũng có thể là chính bạn.","yNghiaNguoc":"Kiếm tuột khỏi tay. Việc giấu bị lộ, hoặc bạn quyết định thú nhận. Cũng có khi là lấy lại được thứ đã mất.","tinhCam":"Có điều giấu nhau. Lòng tin đang bị thử.","congViec":"Coi chừng người không thẳng thắn quanh bạn. Giữ giấy tờ cho rõ.","loiKhuyen":"Đường tắt hôm nay thường là đường vòng của ngày mai."},{"ma":"swords-08","bo":"Kiếm","so":8,"tenVi":"Tám Kiếm","tenEn":"Eight of Swords","tuKhoa":"Tự trói, bất lực, thấy hết đường","yNghiaXuoi":"Người phụ nữ bị bịt mắt và quấn dây giữa tám thanh kiếm cắm quanh. Nhìn kỹ thì dây lỏng, chân không bị trói, và phía trước còn khoảng trống. Bạn thấy mình kẹt, nhưng thứ trói bạn phần lớn là suy nghĩ của chính bạn.","yNghiaNguoc":"Dây được gỡ ra. Bạn nhìn thấy lối thoát, hoặc kẹt sâu hơn vì cứ ngồi yên.","tinhCam":"Cảm thấy mắc kẹt trong mối quan hệ. Bạn có nhiều lựa chọn hơn bạn nghĩ.","congViec":"Thấy không còn đường nào. Hỏi người ngoài, họ sẽ chỉ chỗ bạn không thấy.","loiKhuyen":"Tháo mảnh vải trên mắt ra trước đã, rồi tính tiếp."},{"ma":"swords-09","bo":"Kiếm","so":9,"tenVi":"Chín Kiếm","tenEn":"Nine of Swords","tuKhoa":"Lo âu, mất ngủ, nghĩ quá nhiều","yNghiaXuoi":"Người ngồi bật dậy giữa đêm, hai tay ôm mặt, chín thanh kiếm treo trên tường sau lưng. Chăn thêu hình hoa hồng và các cung hoàng đạo. Nỗi lo đang ở trong đầu bạn chứ không phải ngoài đời, và nửa đêm nó luôn to hơn sự thật.","yNghiaNguoc":"Người ấy buông tay xuống. Nỗi lo dịu đi, hoặc bạn nói ra được với ai đó. Đêm dài đang qua.","tinhCam":"Lo sợ mất người kia tới mức tự làm khổ mình.","congViec":"Áp lực công việc đè lên giấc ngủ. Chia nhỏ vấn đề ra.","loiKhuyen":"Chuyện trong đầu lúc ba giờ sáng thường không đúng như nó tỏ ra."},{"ma":"swords-10","bo":"Kiếm","so":10,"tenVi":"Mười Kiếm","tenEn":"Ten of Swords","tuKhoa":"Chạm đáy, kết thúc đau, hết nạn","yNghiaXuoi":"Người nằm sấp với mười thanh kiếm cắm trên lưng, nhưng phía chân trời đã có vệt sáng. Đến mức này thì không còn xuống được nữa. Một chuyện vừa khép lại theo cách dứt khoát nhất.","yNghiaNguoc":"Kiếm rút ra từng cái. Bạn đang gượng dậy, chuyện tệ nhất đã qua. Hoặc cố kéo dài một thứ đã chết hẳn.","tinhCam":"Một mối quan hệ chấm dứt hoàn toàn. Không cứu được nữa.","congViec":"Thất bại nặng hoặc mất việc. Từ đây chỉ có đi lên.","loiKhuyen":"Chạm đáy cũng là lúc bạn đạp chân xuống mà bật lên."},{"ma":"swords-11","bo":"Kiếm","so":11,"tenVi":"Tiểu Đồng Kiếm","tenEn":"Page of Swords","tuKhoa":"Tò mò, dò hỏi, tin tức","yNghiaXuoi":"Cậu thiếu niên đứng trên gò, giơ kiếm và ngoái nhìn sau lưng, tóc và mây đều bị gió thổi tốc. Người này luôn muốn biết thêm và không ngại hỏi câu khó. Có tin tức đang tới, nhưng cần kiểm lại.","yNghiaNguoc":"Kiếm chúc xuống. Nói nhiều hơn nghĩ, hoặc tọc mạch chuyện người khác. Tin đồn không đáng tin.","tinhCam":"Nhiều câu hỏi chưa được trả lời. Hỏi thẳng thay vì dò xét.","congViec":"Cần học và tìm hiểu thêm trước khi làm. Đừng ngại hỏi.","loiKhuyen":"Hỏi là tốt, nhưng nhớ nghe câu trả lời."},{"ma":"swords-12","bo":"Kiếm","so":12,"tenVi":"Hiệp Sĩ Kiếm","tenEn":"Knight of Swords","tuKhoa":"Lao tới, nói thẳng, vội vàng","yNghiaXuoi":"Ngựa phi hết tốc lực, hiệp sĩ chúi người về trước, kiếm giơ thẳng, cây cối sau lưng đều nghiêng theo gió. Người này lao vào với đầy đủ lý lẽ nhưng không kịp nhìn hai bên.","yNghiaNguoc":"Ngựa khựng lại. Hung hăng gây đổ vỡ, hoặc mất hết đà và chững lại.","tinhCam":"Một người thẳng tính tới mức làm đau. Nói chậm lại một nhịp.","congViec":"Quyết nhanh và làm nhanh, nhưng dễ sót chi tiết quan trọng.","loiKhuyen":"Nhanh thì tốt, miễn là bạn biết mình đang lao về đâu."},{"ma":"swords-13","bo":"Kiếm","so":13,"tenVi":"Hoàng Hậu Kiếm","tenEn":"Queen of Swords","tuKhoa":"Sắc sảo, rạch ròi, từng trải","yNghiaXuoi":"Bà ngồi thẳng, kiếm dựng đứng trong tay phải, tay trái chìa ra như mời nói chuyện. Mây dưới chân ngai đã tan. Người này đi qua nhiều chuyện nên nhìn rất rõ và nói rất thẳng. Nghe thì lạnh, thật ra chỉ là hết tự dối mình.","yNghiaNguoc":"Kiếm hạ xuống ngang. Cay nghiệt, hoặc dựng tường quá cao vì sợ tổn thương lần nữa.","tinhCam":"Cần rõ ràng và giữ ranh giới. Đừng để lòng tốt bị lợi dụng.","congViec":"Nhìn vấn đề tỉnh táo, không bị cảm xúc dẫn. Hợp việc phân tích.","loiKhuyen":"Rạch ròi không làm bạn thành người lạnh lùng."},{"ma":"swords-14","bo":"Kiếm","so":14,"tenVi":"Vua Kiếm","tenEn":"King of Swords","tuKhoa":"Lý trí, công tâm, quyết đoán","yNghiaXuoi":"Ông ngồi nhìn thẳng, kiếm hơi nghiêng sang phải, hai con bướm chạm trên lưng ngai. Người này quyết bằng lý lẽ và giữ nguyên tắc tới cùng. Việc trước mặt cần sự khách quan hơn là sự cảm thông.","yNghiaNguoc":"Kiếm chĩa xuống. Lạnh lùng, áp đặt bằng lý lẽ, hoặc lạm dụng vị trí của mình.","tinhCam":"Cần lý trí lúc này. Bàn cho ra lẽ thay vì tranh hơn thua.","congViec":"Thích hợp cho việc pháp lý, thương lượng, phân xử.","loiKhuyen":"Lý lẽ đúng vẫn cần một chút tình thì người ta mới nghe."},{"ma":"pents-01","bo":"Tiền","so":1,"tenVi":"Át Tiền","tenEn":"Ace of Pentacles","tuKhoa":"Cơ hội vật chất, hạt giống, nền móng","yNghiaXuoi":"Bàn tay từ mây nâng một đồng tiền vàng, bên dưới là vườn hoa huệ và một cổng vòm mở ra núi xa. Một cơ hội cụ thể về tiền bạc hoặc công việc đang tới tay bạn, không hào nhoáng nhưng chắc và xây lên được.","yNghiaNguoc":"Tay buông ra, đồng tiền rơi mất. Cơ hội trôi mất vì bạn chần chừ, hoặc một khoản đầu tư không như mong đợi.","tinhCam":"Có nền tảng thực tế, không chỉ là cảm xúc.","congViec":"Việc mới, nguồn thu mới, hoặc vốn để bắt đầu. Nắm lấy.","loiKhuyen":"Cơ hội tốt thường trông rất bình thường lúc mới tới."},{"ma":"pents-02","bo":"Tiền","so":2,"tenVi":"Hai Tiền","tenEn":"Two of Pentacles","tuKhoa":"Xoay xở, cân đối, nhiều việc một lúc","yNghiaXuoi":"Chàng trai tung hứng hai đồng tiền nối nhau bằng dải vô cực, sau lưng là hai con thuyền nhấp nhô trên sóng lớn. Bạn đang cùng lúc giữ nhiều thứ và vẫn giữ được, nhưng sóng phía sau nhắc rằng không giữ được mãi.","yNghiaNguoc":"Một đồng rơi xuống. Quá tải, thu chi mất cân đối, việc nọ đè việc kia.","tinhCam":"Chia thời gian cho người kia chưa hợp lý.","congViec":"Nhiều việc cùng lúc. Sắp thứ tự trước khi có thứ rơi.","loiKhuyen":"Tung hứng giỏi đến mấy cũng có lúc phải đặt bớt xuống."},{"ma":"pents-03","bo":"Tiền","so":3,"tenVi":"Ba Tiền","tenEn":"Three of Pentacles","tuKhoa":"Hợp lực, tay nghề, được ghi nhận","yNghiaXuoi":"Người thợ đá đứng trên ghế làm việc, hai người cầm bản vẽ đứng nghe. Mỗi người giỏi một phần và việc này cần cả ba. Tay nghề của bạn đang được nhìn nhận. Đừng ôm hết vào mình.","yNghiaNguoc":"Bản vẽ gấp lại. Làm việc nhóm trục trặc, hoặc công sức không ai nhìn thấy. Cũng có khi là làm cho xong.","tinhCam":"Hai người cùng xây một thứ chung. Cần chia việc rõ ràng.","congViec":"Được đánh giá cao về chuyên môn. Cơ hội hợp tác tốt.","loiKhuyen":"Một mình nhanh hơn, nhưng cùng nhau mới đi xa."},{"ma":"pents-04","bo":"Tiền","so":4,"tenVi":"Bốn Tiền","tenEn":"Four of Pentacles","tuKhoa":"Giữ chặt, tiết kiệm, sợ mất","yNghiaXuoi":"Người đàn ông ôm chặt một đồng tiền vào ngực, đội một đồng trên đầu, giẫm hai đồng dưới chân. Ông giữ kỹ tới mức không cử động được. Bạn đang nắm rất chặt thứ mình có, an toàn thì có nhưng cũng không nhận thêm được gì.","yNghiaNguoc":"Tay nới ra. Bạn bắt đầu cho đi, hoặc ngược lại, tiêu hoang sau một thời gian kìm nén.","tinhCam":"Giữ người kia quá chặt, hoặc khép lòng không cho ai vào.","congViec":"Giữ tiền là đúng lúc này, nhưng đừng bỏ lỡ cơ hội đáng đầu tư.","loiKhuyen":"Nắm chặt quá thì tay không mở ra nhận được gì nữa."},{"ma":"pents-05","bo":"Tiền","so":5,"tenVi":"Năm Tiền","tenEn":"Five of Pentacles","tuKhoa":"Thiếu thốn, bị bỏ rơi, khó khăn","yNghiaXuoi":"Hai người đi chân trần trong tuyết, một người chống nạng, ngang qua ô cửa kính màu sáng đèn mà không ai ngẩng lên nhìn. Bạn đang chật vật về tiền bạc hoặc sức khoẻ, kèm cảm giác không ai đứng cùng. Nhưng chỗ sáng vẫn ở ngay cạnh.","yNghiaNguoc":"Hai người bước vào trong. Khó khăn đang qua, có người chìa tay ra. Hoặc bạn tự cô lập nên không ai giúp được.","tinhCam":"Cảm thấy cô đơn ngay trong mối quan hệ. Nói ra đi.","congViec":"Thu nhập giảm hoặc mất việc. Đây là lúc nhờ vả, không phải lúc sĩ diện.","loiKhuyen":"Cửa vẫn sáng ngay bên cạnh. Chỉ là bạn đang không ngẩng lên."},{"ma":"pents-06","bo":"Tiền","so":6,"tenVi":"Sáu Tiền","tenEn":"Six of Pentacles","tuKhoa":"Cho và nhận, giúp đỡ, sòng phẳng","yNghiaXuoi":"Người giàu một tay cầm cân một tay thả tiền cho hai người quỳ dưới. Cái cân mới là chi tiết đáng chú ý, vì nó đo xem cho bao nhiêu là đủ. Đang có sự trao đổi qua lại giữa bạn và ai đó.","yNghiaNguoc":"Cân lệch. Cho đi mà kèm điều kiện, hoặc nhận mãi mà không trả. Quan hệ đang nghiêng hẳn về một bên.","tinhCam":"Một bên luôn cho, một bên luôn nhận. Cần chỉnh lại.","congViec":"Có người giúp đỡ, hoặc đến lượt bạn giúp người khác. Tiền bạc ổn lên.","loiKhuyen":"Hôm nay bạn cho, ngày khác bạn nhận. Đừng đếm quá kỹ."},{"ma":"pents-07","bo":"Tiền","so":7,"tenVi":"Bảy Tiền","tenEn":"Seven of Pentacles","tuKhoa":"Chờ mùa, kiên nhẫn, xem lại","yNghiaXuoi":"Người nông dân tì cằm lên cán cuốc, nhìn bụi cây đã kết sáu đồng tiền, một đồng nằm dưới chân. Ông không hái, ông đang tính. Bạn đang ở quãng đánh giá xem công sức bỏ ra có sinh lợi không.","yNghiaNguoc":"Ông bỏ cuốc đi. Sốt ruột muốn hái non, hoặc nhận ra đã đầu tư vào chỗ không sinh lời.","tinhCam":"Cần thêm thời gian mới rõ. Đừng ép.","congViec":"Kết quả chưa tới ngay. Xem lại cách làm rồi kiên nhẫn thêm.","loiKhuyen":"Cây chưa ra quả không có nghĩa là bạn trồng sai."},{"ma":"pents-08","bo":"Tiền","so":8,"tenVi":"Tám Tiền","tenEn":"Eight of Pentacles","tuKhoa":"Rèn nghề, chăm chỉ, làm kỹ","yNghiaXuoi":"Người thợ cặm cụi khắc đồng tiền thứ tám, bảy đồng đã xong treo ngay ngắn bên cạnh, thành phố ở phía xa. Anh ta không nhìn đi đâu khác, và bạn đang giỏi lên theo đúng cách đó, nhờ lặp đi lặp lại chứ không nhờ may mắn.","yNghiaNguoc":"Đồng tiền khắc hỏng. Làm cho xong, chất lượng đi xuống. Hoặc chán việc mình đang làm.","tinhCam":"Cần vun vén mỗi ngày, không có đường tắt.","congViec":"Học nghề, nâng tay nghề. Sự chăm chỉ sẽ được trả công.","loiKhuyen":"Giỏi là thứ tích cóp từng ngày, không ai cho không."},{"ma":"pents-09","bo":"Tiền","so":9,"tenVi":"Chín Tiền","tenEn":"Nine of Pentacles","tuKhoa":"Tự lập, dư dả, hưởng thành quả","yNghiaXuoi":"Người phụ nữ đứng trong vườn nho chín, con chim ưng đậu trên tay đeo găng, ngôi nhà ở phía sau. Con chim được huấn luyện, nghĩa là bà tự làm chủ cả thứ hoang dã trong mình. Bạn đứng được bằng chân mình và có quyền hưởng thứ tự tay gây dựng.","yNghiaNguoc":"Vườn nho bỏ hoang. Phụ thuộc người khác về tài chính, hoặc có đủ đầy mà vẫn thấy cô đơn.","tinhCam":"Tự tin và độc lập. Không cần ai để thấy mình đủ.","congViec":"Ổn định tài chính. Thành quả của nhiều năm tích luỹ.","loiKhuyen":"Bạn tự làm ra thứ này. Cứ hưởng cho thoải mái."},{"ma":"pents-10","bo":"Tiền","so":10,"tenVi":"Mười Tiền","tenEn":"Ten of Pentacles","tuKhoa":"Bền vững, gia sản, lâu dài","yNghiaXuoi":"Ba thế hệ trong một sân nhà, ông già ngồi với hai con chó, đôi vợ chồng và đứa trẻ đứng gần. Mười đồng tiền rải khắp tranh. Thứ bạn đang xây không chỉ cho mình. Nó còn để lại cho người sau, và đó mới là chỗ đáng giá.","yNghiaNguoc":"Sân nhà vắng người. Tranh chấp tài sản, hoặc gánh nặng gia đình. Cũng có khi thứ tưởng ổn định đang lung lay.","tinhCam":"Hướng tới lâu dài, có sự đồng thuận của gia đình.","congViec":"Đầu tư dài hạn, tài sản lớn, chuyện thừa kế.","loiKhuyen":"Thứ đáng xây là thứ còn lại sau khi bạn đi."},{"ma":"pents-11","bo":"Tiền","so":11,"tenVi":"Tiểu Đồng Tiền","tenEn":"Page of Pentacles","tuKhoa":"Học việc, dự định mới, chăm chỉ","yNghiaXuoi":"Cậu thiếu niên nâng đồng tiền lên ngang mắt và ngắm nghía, đứng giữa đồng cỏ xanh. Cậu chưa làm gì cả, mới đang học cách nhìn. Bạn đang bắt đầu một việc nhỏ nhưng nghiêm túc, chẳng hạn đi học, nhận việc mới, hay tập để dành.","yNghiaNguoc":"Cậu đánh rơi đồng tiền. Bỏ dở việc học, hoặc dự định mãi không bắt đầu. Cũng có khi là tiêu tiền thiếu tính toán.","tinhCam":"Giai đoạn tìm hiểu, từ từ mà chắc.","congViec":"Cơ hội học nghề hoặc một việc mới. Chịu khó thì sẽ tiến.","loiKhuyen":"Bắt đầu nhỏ cũng được, miễn là bắt đầu thật."},{"ma":"pents-12","bo":"Tiền","so":12,"tenVi":"Hiệp Sĩ Tiền","tenEn":"Knight of Pentacles","tuKhoa":"Chậm mà chắc, đáng tin, bền bỉ","yNghiaXuoi":"Con ngựa đen đứng yên hoàn toàn, hiệp sĩ nâng đồng tiền và nhìn nó, phía sau là ruộng đã cày xong. Trong cả bộ bài, chỉ mình hiệp sĩ này đứng yên. Người này không nhanh và không hoa mỹ, nhưng làm là tới nơi.","yNghiaNguoc":"Ngựa đứng mãi không đi. Trì trệ, bảo thủ, làm hoài một cách cũ. Hoặc chậm tới mức lỡ mất cơ hội.","tinhCam":"Một người đáng tin nhưng hơi thiếu bất ngờ. Bền thì rất bền.","congViec":"Tiến chậm nhưng không lùi. Giữ nhịp là được.","loiKhuyen":"Chậm không phải là vấn đề. Dừng hẳn mới là."},{"ma":"pents-13","bo":"Tiền","so":13,"tenVi":"Hoàng Hậu Tiền","tenEn":"Queen of Pentacles","tuKhoa":"Chu toàn, vun vén, thực tế","yNghiaXuoi":"Bà ngồi trên ngai chạm đầy hoa trái và dê, ôm đồng tiền trong lòng như ôm một đứa trẻ, con thỏ nhảy ở góc tranh. Người này lo được cho cả nhà mà vẫn giữ được việc của mình. Sự ấm áp ở đây thể hiện bằng việc làm chứ không bằng lời.","yNghiaNguoc":"Đồng tiền đặt xuống đất. Lo cho người khác tới mức quên bản thân, hoặc quá đặt nặng chuyện tiền nong.","tinhCam":"Một người biết chăm sóc và biết lo xa. Đáng để dựa vào.","congViec":"Quản lý tốt tiền bạc và công việc. Cân được cả hai bên.","loiKhuyen":"Lo cho người khác thì nhớ chừa lại phần cho mình."},{"ma":"pents-14","bo":"Tiền","so":14,"tenVi":"Vua Tiền","tenEn":"King of Pentacles","tuKhoa":"Vững vàng, thành đạt, rộng rãi","yNghiaXuoi":"Ông ngồi giữa giàn nho trĩu quả, áo thêu đầy chùm nho, toà lâu đài phía sau là thứ ông tự xây. Người này đã dựng xong nền móng và giờ đủ sức nâng người khác. Thành công ở đây đến từ nhiều năm bền bỉ, không từ một cú may.","yNghiaNguoc":"Giàn nho héo. Bủn xỉn, hoặc lấy tiền bạc làm thước đo cho mọi thứ. Cũng có khi là bảo thủ trong làm ăn.","tinhCam":"Một người vững chãi, lo được. Có nền tảng thực tế.","congViec":"Làm ăn thuận lợi, đầu tư sinh lời. Có thể dẫn dắt người khác.","loiKhuyen":"Có rồi thì mở tay ra. Đó mới là chỗ tiền có giá trị nhất."}];
export const MAU_CUNG = [{"ma":"aries","ten":"Bạch Dương","ten_en":"Aries","tu_ngay":"21/3","den_ngay":"19/4","nguyen_to":"Hoả","tinh_chat":"Khởi đầu","tinh_cach":"Bạn nghĩ tới đâu làm tới đó, và thường là người khởi động mọi chuyện trong nhóm. Nhiệt tình của bạn lây sang người khác rất nhanh, nhưng cũng nguội nhanh nếu việc kéo dài quá.","diem_manh":"Dũng cảm, thẳng thắn, dám làm trước khi thấy đủ điều kiện, không để bụng lâu.","diem_yeu":"Nóng tính, thiếu kiên nhẫn, hay bỏ dở, đôi khi không để ý người khác nghĩ gì."},{"ma":"taurus","ten":"Kim Ngưu","ten_en":"Taurus","tu_ngay":"20/4","den_ngay":"20/5","nguyen_to":"Thổ","tinh_chat":"Ổn định","tinh_cach":"Bạn thích mọi thứ chắc chắn và không ưa bị giục. Bạn xây dựng chậm nhưng thứ bạn có thường giữ được lâu, cả về của cải lẫn quan hệ.","diem_manh":"Bền bỉ, đáng tin, thực tế, biết tận hưởng và biết vun vén.","diem_yeu":"Bảo thủ, ngại đổi, cố chấp khi đã quyết, đôi khi quá coi trọng vật chất."},{"ma":"gemini","ten":"Song Tử","ten_en":"Gemini","tu_ngay":"21/5","den_ngay":"20/6","nguyen_to":"Khí","tinh_chat":"Linh hoạt","tinh_cach":"Đầu bạn lúc nào cũng chạy và bạn cần cái mới để không thấy chán. Bạn nói chuyện hợp với nhiều kiểu người vì bạn thật sự tò mò về họ.","diem_manh":"Nhanh nhạy, hoạt ngôn, học nhanh, thích nghi tốt với thay đổi.","diem_yeu":"Hay đổi ý, khó tập trung lâu, dễ hứa rồi quên, đôi khi nông."},{"ma":"cancer","ten":"Cự Giải","ten_en":"Cancer","tu_ngay":"21/6","den_ngay":"22/7","nguyen_to":"Thuỷ","tinh_chat":"Khởi đầu","tinh_cach":"Bạn để ý tới cảm xúc của người khác trước khi họ kịp nói. Gia đình và vài người thân thiết là trung tâm đời bạn, và bạn bảo vệ họ rất kỹ.","diem_manh":"Ấm áp, tận tuỵ, nhớ dai những điều tử tế, chăm sóc người khác rất khéo.","diem_yeu":"Dễ tủi thân, hay giữ trong lòng, bám víu quá khứ, tâm trạng lên xuống."},{"ma":"leo","ten":"Sư Tử","ten_en":"Leo","tu_ngay":"23/7","den_ngay":"22/8","nguyen_to":"Hoả","tinh_chat":"Ổn định","tinh_cach":"Bạn có mặt ở đâu là người ta để ý ở đó, và bạn cũng thích như vậy. Bạn hào phóng với người mình quý, và rất khó chịu khi bị coi thường.","diem_manh":"Tự tin, rộng rãi, trung thành, dám đứng ra chịu trách nhiệm.","diem_yeu":"Sĩ diện, cần được khen, dễ tự ái, đôi khi lấn át người khác."},{"ma":"virgo","ten":"Xử Nữ","ten_en":"Virgo","tu_ngay":"23/8","den_ngay":"22/9","nguyen_to":"Thổ","tinh_chat":"Linh hoạt","tinh_cach":"Bạn nhìn ra chi tiết mà người khác bỏ qua, và bạn khó chịu khi thấy thứ gì đó làm ẩu. Bạn giúp người khác bằng việc làm chứ ít khi bằng lời.","diem_manh":"Tỉ mỉ, có trách nhiệm, phân tích tốt, làm gì cũng tới nơi tới chốn.","diem_yeu":"Hay soi, khó hài lòng, lo lắng quá mức, khắt khe với chính mình."},{"ma":"libra","ten":"Thiên Bình","ten_en":"Libra","tu_ngay":"23/9","den_ngay":"22/10","nguyen_to":"Khí","tinh_chat":"Khởi đầu","tinh_cach":"Bạn ghét không khí căng thẳng và thường là người dàn xếp. Bạn nhìn được cả hai phía của một câu chuyện, nên đôi khi khó chọn phía nào.","diem_manh":"Công bằng, dễ chịu, biết cách cư xử, giỏi hoà giải.","diem_yeu":"Khó quyết, hay chiều lòng người, né tránh va chạm, dễ bị lung lay."},{"ma":"scorpio","ten":"Bọ Cạp","ten_en":"Scorpio","tu_ngay":"23/10","den_ngay":"21/11","nguyen_to":"Thuỷ","tinh_chat":"Ổn định","tinh_cach":"Bạn ít nói về mình nhưng nhìn thấu người khác rất nhanh. Khi đã dốc lòng vào ai hay việc gì thì bạn dốc tới cùng.","diem_manh":"Sâu sắc, ý chí mạnh, trung thành tuyệt đối, không sợ chuyện khó.","diem_yeu":"Đa nghi, để bụng lâu, kiểm soát, khó tha thứ khi bị phản bội."},{"ma":"sagittarius","ten":"Nhân Mã","ten_en":"Sagittarius","tu_ngay":"22/11","den_ngay":"21/12","nguyen_to":"Hoả","tinh_chat":"Linh hoạt","tinh_cach":"Bạn cần không gian để thở và ghét bị bó buộc. Bạn thích đi, thích học thứ mới, và nói chuyện rất thẳng dù đôi khi hơi vô ý.","diem_manh":"Lạc quan, phóng khoáng, ham hiểu biết, thật thà tới mức thẳng đuột.","diem_yeu":"Thiếu kiên nhẫn, hứa dễ quên, nói không nghĩ, ngại cam kết dài."},{"ma":"capricorn","ten":"Ma Kết","ten_en":"Capricorn","tu_ngay":"22/12","den_ngay":"19/1","nguyen_to":"Thổ","tinh_chat":"Khởi đầu","tinh_cach":"Bạn đặt mục tiêu rồi đi tới đó, không ồn ào và không tắt giữa chừng. Bạn trưởng thành sớm hơn bạn bè cùng tuổi và tự đòi hỏi mình rất cao.","diem_manh":"Kỷ luật, kiên trì, có trách nhiệm, nhìn được đường dài.","diem_yeu":"Khô khan, ôm việc, khó thả lỏng, hay tự trách mình quá nặng."},{"ma":"aquarius","ten":"Bảo Bình","ten_en":"Aquarius","tu_ngay":"20/1","den_ngay":"18/2","nguyen_to":"Khí","tinh_chat":"Ổn định","tinh_cach":"Bạn nghĩ khác đám đông và không thấy đó là vấn đề. Bạn quan tâm tới những chuyện lớn hơn phần mình, nhưng lại hơi xa cách trong quan hệ gần.","diem_manh":"Độc lập, cởi mở, nhiều ý tưởng lạ, không phân biệt đối xử.","diem_yeu":"Bướng, xa cách về cảm xúc, khó gần, đôi khi cố tình khác người."},{"ma":"pisces","ten":"Song Ngư","ten_en":"Pisces","tu_ngay":"19/2","den_ngay":"20/3","nguyen_to":"Thuỷ","tinh_chat":"Linh hoạt","tinh_cach":"Bạn cảm nhận được tâm trạng người khác gần như ngay lập tức. Bạn giàu tưởng tượng và dễ mềm lòng, nên hay nhận phần thiệt về mình.","diem_manh":"Đồng cảm, giàu tưởng tượng, dịu dàng, sẵn lòng vì người khác.","diem_yeu":"Cả nể, dễ bị lợi dụng, hay trốn vào thế giới riêng, thiếu dứt khoát."}];
export const MAU_DO_HOP = [{"cung_a":"aries","cung_b":"aries","diem":4,"loi_binh":"Muốn gì làm nấy, nói là làm luôn, nên chẳng ai phải chờ ai. Rắc rối nằm ở lúc hai người cùng nổi nóng, vì không còn ai đứng ngoài để kéo lại. Chuyện bé xé ra to rất nhanh, rồi hôm sau cả hai quên sạch.","diem_manh":"Không ai phải đoán ý ai. Muốn gì nói thẳng, quyết nhanh, sống rất đã.","diem_yeu":"Cùng nóng, cùng bướng, cùng không chịu xin lỗi trước.","loi_khuyen":"Thống nhất trước một câu dừng, cãi tới đó thì tạm tách ra."},{"cung_a":"aries","cung_b":"taurus","diem":3,"loi_binh":"Bạch Dương đã quyết là đi ngay, Kim Ngưu phải ngắm nghía chán chê mới nhúc nhích. Hai nhịp này không xung nhau mà chỉ lệch nhau, nên rốt cuộc Bạch Dương sốt ruột còn Kim Ngưu thì khó chịu vì bị giục.","diem_manh":"Một người đẩy đi, một người giữ lại. Cân được thì vừa dám làm vừa không hớ.","diem_yeu":"Giục Kim Ngưu là họ càng lì. Chờ Bạch Dương chín chắn thì chờ lâu.","loi_khuyen":"Chia việc theo thế mạnh, đừng bắt nhau chạy cùng một tốc độ."},{"cung_a":"aries","cung_b":"gemini","diem":4,"loi_binh":"Bạch Dương thích lao vào, Song Tử thích nghĩ ra trò mới, nên hai người hiếm khi ngồi yên. Song Tử nói mãi mà Bạch Dương không chán, Bạch Dương làm liều mà Song Tử không sợ, vui thì rất vui nhưng sâu thì chưa.","diem_manh":"Không bao giờ buồn chán. Có ý tưởng là có người bắt tay vào ngay.","diem_yeu":"Cả hai đều nhanh nguội. Bắt đầu mười thứ, xong được hai.","loi_khuyen":"Chọn một việc rồi theo cho tới, đừng để dở dang chất đống."},{"cung_a":"aries","cung_b":"cancer","diem":2,"loi_binh":"Bạch Dương nói thẳng ruột ngựa, Cự Giải nghe xong về nghĩ ba ngày. Bạch Dương tưởng đã xong chuyện, Cự Giải vẫn còn đau mà không nói. Cùng một câu nói, hai người hiểu ra hai nghĩa khác hẳn nhau. Cự Giải cần được hỏi han trước khi nghe góp ý, điều mà Bạch Dương hiếm khi nghĩ tới.","diem_manh":"Cự Giải lo được phần ấm áp mà Bạch Dương thiếu. Bạch Dương che chắn được cho Cự Giải.","diem_yeu":"Một bên nói cho nhẹ lòng, một bên nghe rồi cất vào bụng.","loi_khuyen":"Bạch Dương hạ giọng một nhịp. Cự Giải nói ra ngay thay vì để nguội."},{"cung_a":"aries","cung_b":"leo","diem":5,"loi_binh":"Hai cung lửa gặp nhau, ai cũng muốn nổi bật mà lại thích nhìn người kia nổi bật. Bạch Dương xông lên trước, Sư Tử đứng sau cổ vũ rồi cả hai cùng đi tới. Sống rất rộn và hiếm khi tẻ nhạt. Chỗ phải giữ ý là lời nói lúc nóng, vì cả hai đều nhớ rất lâu câu làm mình mất mặt.","diem_manh":"Cùng nhiệt, cùng dám, và cùng thích thấy người kia được ghi nhận.","diem_yeu":"Sĩ diện cả hai. Một câu nói hớ là giận nhau mấy ngày.","loi_khuyen":"Khen nhau thật lòng trước mặt người khác, hiệu quả hơn mọi lời giải thích."},{"cung_a":"aries","cung_b":"virgo","diem":1,"loi_binh":"Bạch Dương làm xong rồi tính, Xử Nữ tính xong mới làm. Xử Nữ nhìn đâu cũng thấy chỗ cần sửa, mà Bạch Dương thì ghét nhất bị sửa lưng. Hai người này lệch nhau từ cách nghĩ tới cách tiêu tiền.","diem_manh":"Xử Nữ vá được những lỗ hổng Bạch Dương bỏ qua.","diem_yeu":"Góp ý của Xử Nữ vào tai Bạch Dương thành chê bai. Sự vội của Bạch Dương vào mắt Xử Nữ thành ẩu.","loi_khuyen":"Xử Nữ góp ý một lần thôi. Bạch Dương nghe hết câu rồi hẵng phản ứng."},{"cung_a":"aries","cung_b":"libra","diem":3,"loi_binh":"Bạch Dương quyết trong ba giây, Thiên Bình cân nhắc ba ngày. Bạch Dương sẵn sàng va chạm, Thiên Bình né đến cùng. Hai người ở hai cực nên vừa thấy đối phương có thứ mình thiếu, vừa thấy đối phương khó hiểu.","diem_manh":"Thiên Bình làm mềm cái sắc của Bạch Dương. Bạch Dương cho Thiên Bình chỗ dựa để dám chọn.","diem_yeu":"Thiên Bình chiều mãi rồi ấm ức. Bạch Dương tưởng im lặng là đồng ý.","loi_khuyen":"Thiên Bình nói ra lúc chưa bực. Bạch Dương hỏi lại thay vì tự suy ra."},{"cung_a":"aries","cung_b":"scorpio","diem":1,"loi_binh":"Mạnh thì ai cũng mạnh, nhưng mạnh theo hai kiểu không gặp nhau. Bạch Dương bùng lên rồi tắt, Bọ Cạp nén lại và nhớ rất lâu. Bạch Dương cãi xong là quên, Bọ Cạp cất từng câu vào một chỗ riêng.","diem_manh":"Khi đã cùng nhìn về một hướng thì không mấy ai cản nổi hai người.","diem_yeu":"Bạch Dương sống phô ra, Bọ Cạp giữ kín. Một bên thấy bị giấu, một bên thấy bị soi.","loi_khuyen":"Bọ Cạp nói ra điều đang để bụng. Bạch Dương đừng ép đối phương mở ngay."},{"cung_a":"aries","cung_b":"sagittarius","diem":5,"loi_binh":"Ghét bị trói, thích đi, và nói thẳng tới mức người ngoài nghe phải giật mình. Bạch Dương châm lửa, Nhân Mã thổi cho cháy to. Chẳng ai bắt ai phải giải thích vì sao lại muốn đổi kế hoạch giữa chừng. Đây là một trong vài cặp hiếm hoi mà cãi nhau xong là xong thật.","diem_manh":"Tự do mà vẫn đi chung đường. Cãi nhau xong là quên, không ai để bụng.","diem_yeu":"Không ai chịu làm người giữ tiền và giữ lịch.","loi_khuyen":"Giao phần sổ sách cho một người, hoặc cho người thứ ba."},{"cung_a":"aries","cung_b":"capricorn","diem":2,"loi_binh":"Bạch Dương muốn kết quả ngay hôm nay, Ma Kết tính đường năm năm. Cả hai đều muốn cầm trịch và đều tin cách của mình đúng. Va nhau thì nảy lửa, mà hợp nhau thì làm được việc lớn.","diem_manh":"Sức bật của Bạch Dương cộng với kỷ luật của Ma Kết là một cặp làm ăn đáng gờm.","diem_yeu":"Ma Kết thấy Bạch Dương bốc đồng. Bạch Dương thấy Ma Kết khô và chậm.","loi_khuyen":"Phân vai rõ ai quyết việc gì, đừng để hai người cùng cầm một việc."},{"cung_a":"aries","cung_b":"aquarius","diem":4,"loi_binh":"Bảo Bình nghĩ ra thứ chưa ai làm, Bạch Dương là người dám làm thử. Cả hai đều không thích bị bảo phải sống thế nào. Bảo Bình để Bạch Dương tự do, và đó đúng là thứ Bạch Dương cần nhất.","diem_manh":"Không ai bám lấy ai. Cho nhau khoảng riêng mà vẫn thân.","diem_yeu":"Bảo Bình lạnh lúc Bạch Dương đang cần một phản ứng.","loi_khuyen":"Bảo Bình đáp lại bằng cảm xúc thật, dù chỉ một câu ngắn."},{"cung_a":"aries","cung_b":"pisces","diem":3,"loi_binh":"Bạch Dương bước thẳng, Song Ngư đi vòng. Song Ngư cảm được điều Bạch Dương chưa kịp nói, nhưng cũng dễ tổn thương vì chính cái thẳng ấy. Bạch Dương thường không biết mình vừa làm đau đối phương.","diem_manh":"Song Ngư làm dịu Bạch Dương. Bạch Dương kéo Song Ngư ra khỏi những nỗi lo tự nghĩ ra.","diem_yeu":"Song Ngư giận mà không nói. Bạch Dương nói mà không để ý người nghe.","loi_khuyen":"Bạch Dương hỏi một câu trước khi kết luận. Song Ngư trả lời thật thay vì nói không sao."},{"cung_a":"taurus","cung_b":"taurus","diem":4,"loi_binh":"Thích yên, thích chắc, thích ăn ngon và ngại xáo trộn. Nhà cửa gọn gàng, tiền nong rõ ràng, chẳng mấy khi có bất ngờ. Chỉ là khi hai cái lì gặp nhau thì không ai chịu bước xuống trước.","diem_manh":"Rất bền. Đã chọn nhau rồi thì hiếm khi đổi ý.","diem_yeu":"Cùng ngại thay đổi nên dễ giậm chân một chỗ. Giận nhau thì im lặng cả tuần.","loi_khuyen":"Mỗi tháng thử một thứ mới, dù chỉ là đổi quán ăn."},{"cung_a":"taurus","cung_b":"gemini","diem":3,"loi_binh":"Kim Ngưu muốn mọi thứ nguyên chỗ, Song Tử ngày nào cũng muốn khác đi một chút. Song Tử nói liên hồi, Kim Ngưu nghe và không thấy cần đáp lại hết. Hai người sống cạnh nhau được, chỉ là ít khi thật sự hiểu nhau cần gì.","diem_manh":"Song Tử làm Kim Ngưu bớt cũ. Kim Ngưu cho Song Tử một chỗ để quay về.","diem_yeu":"Song Tử thấy ngột ngạt, Kim Ngưu thấy bất an.","loi_khuyen":"Song Tử báo trước khi đổi kế hoạch. Kim Ngưu đừng coi mọi thay đổi là mối đe doạ."},{"cung_a":"taurus","cung_b":"cancer","diem":4,"loi_binh":"Mái ấm là thứ cả hai lấy làm gốc. Kim Ngưu lo phần vật chất, Cự Giải lo phần tinh thần, và không ai thấy phần của người kia là chuyện vặt. Với hai người, bữa cơm tối nói được nhiều hơn mọi lời hứa. Tiền bạc hiếm khi thành đề tài cãi nhau.","diem_manh":"Gắn bó chặt cả về chuyện tiền lẫn chuyện lòng. Rất hợp để tính chuyện lâu dài.","diem_yeu":"Cùng ngại ra ngoài, dễ co lại thành một thế giới chỉ có hai người.","loi_khuyen":"Giữ liên lạc với bạn bè hai bên, đừng để cả hai cùng khép lại."},{"cung_a":"taurus","cung_b":"leo","diem":2,"loi_binh":"Sư Tử thích phô, Kim Ngưu thích giữ. Sư Tử tiêu cho đẹp mặt, Kim Ngưu đếm từng đồng. Cả hai cùng bướng ngang nhau nên tới lúc va thì không bên nào lùi.","diem_manh":"Cả hai đều chung thuỷ và đều muốn một thứ bền. Gốc giống nhau hơn vẻ ngoài.","diem_yeu":"Tiền bạc là chỗ cãi nhau nhiều nhất. Rồi tới chuyện ai được chú ý hơn.","loi_khuyen":"Thống nhất một khoản tiêu chung, ngoài khoản đó thì ai tiêu kiểu nấy."},{"cung_a":"taurus","cung_b":"virgo","diem":5,"loi_binh":"Hai cung đất gặp nhau, cùng thực tế, cùng biết lo xa, cùng không thích nói chuyện trên mây. Kim Ngưu làm chắc, Xử Nữ làm kỹ, nên việc gì giao cho cặp này cũng xong. Sống với nhau rất yên. Cái yên đó giữ được lâu, nhưng phải có người chủ động làm cho nó ấm lên.","diem_manh":"Tin nhau được. Không ai phải nhắc ai về trách nhiệm.","diem_yeu":"Cùng khô. Lâu ngày thành bạn cùng nhà hơn là người yêu.","loi_khuyen":"Dành riêng một buổi mỗi tuần không bàn chuyện tiền và chuyện việc."},{"cung_a":"taurus","cung_b":"libra","diem":1,"loi_binh":"Thích cái đẹp là điểm chung duy nhất, và cũng chỉ giống nhau tới đó. Thiên Bình cần ra ngoài, cần người, cần không khí mới. Kim Ngưu chỉ muốn về nhà. Thiên Bình ngại nói thẳng, Kim Ngưu chờ được nói rõ mới chịu.","diem_manh":"Cả hai đều ghét xung đột nên nhà cửa êm.","diem_yeu":"Êm bên ngoài mà dồn nén bên trong. Chuyện cũ không ai chịu mở ra.","loi_khuyen":"Mỗi tháng nói hết một chuyện còn tồn, dù không khí có hơi căng."},{"cung_a":"taurus","cung_b":"scorpio","diem":3,"loi_binh":"Nằm đối nhau trên vòng hoàng đạo nên hút nhau rất mạnh ngay từ đầu. Kim Ngưu chắc và lộ, Bọ Cạp sâu và kín. Cả hai đều rất chung thuỷ và cũng đều rất sở hữu, nên yêu thì hết mình mà ghen cũng hết mình.","diem_manh":"Gắn bó sâu, ít cặp nào bền được như cặp này khi đã qua được giai đoạn đầu.","diem_yeu":"Hai cái bướng cộng với hai cái ghen. Đã giận là rất lâu mới nguôi.","loi_khuyen":"Nói ra điều đang nghi ngay lúc nó còn nhỏ, đừng nuôi nó lớn."},{"cung_a":"taurus","cung_b":"sagittarius","diem":1,"loi_binh":"Kim Ngưu muốn cắm rễ, Nhân Mã muốn xách ba lô, một bên để dành còn một bên tiêu cho chuyến đi tới. Gần như mọi thứ quan trọng với người này đều là thứ người kia thấy không cần thiết.","diem_manh":"Nhân Mã kéo Kim Ngưu ra khỏi nhà. Kim Ngưu cho Nhân Mã chỗ để quay về.","diem_yeu":"Tiền và tự do, hai chuyện này cãi mãi không xong.","loi_khuyen":"Tách tài khoản ra, và đừng ai bắt ai phải đổi lối sống."},{"cung_a":"taurus","cung_b":"capricorn","diem":5,"loi_binh":"Việc làm nói thay lời, cả hai cùng tin như vậy. Kim Ngưu xây nền, Ma Kết dựng lên, và cả hai đều kiên nhẫn chờ được. Mười năm sau nhìn lại, hai người đã có cả một cơ ngơi mà không mấy khi phải bàn to tiếng.","diem_manh":"Rất đáng tin cậy với nhau. Kế hoạch dài hạn nào cũng chạy được.","diem_yeu":"Lo làm quá nên quên mất phần tình cảm. Cả hai đều ngại nói lời ngọt.","loi_khuyen":"Nói ra một câu khen mỗi tuần, dù nghe có hơi ngượng."},{"cung_a":"taurus","cung_b":"aquarius","diem":2,"loi_binh":"Bảo Bình thích phá lệ, Kim Ngưu sống bằng lệ. Bảo Bình đổi ý và đổi hướng theo cách Kim Ngưu không tài nào đoán được. Càng bị giữ chặt Bảo Bình càng muốn đi, mà càng thấy đối phương muốn đi thì Kim Ngưu càng giữ.","diem_manh":"Bảo Bình mở mắt cho Kim Ngưu. Kim Ngưu cho Bảo Bình thứ nền mà họ vẫn thiếu.","diem_yeu":"Một bên cần chắc chắn, một bên dị ứng với chắc chắn.","loi_khuyen":"Thoả thuận rõ cái gì cố định, ngoài ra thì để nhau tự do."},{"cung_a":"taurus","cung_b":"pisces","diem":4,"loi_binh":"Song Ngư mơ, Kim Ngưu biến giấc mơ thành thứ sờ được. Kim Ngưu không chê Song Ngư viển vông, Song Ngư không chê Kim Ngưu thực dụng. Hai người bù cho nhau một cách khá tự nhiên.","diem_manh":"Kim Ngưu cho Song Ngư cảm giác an toàn. Song Ngư làm đời Kim Ngưu bớt khô.","diem_yeu":"Song Ngư cả nể nên hay nhận lời bừa. Kim Ngưu phải dọn hậu quả.","loi_khuyen":"Kim Ngưu giúp Song Ngư tập nói lời từ chối."},{"cung_a":"gemini","cung_b":"gemini","diem":4,"loi_binh":"Nói chuyện với nhau không bao giờ hết đề tài, nhảy từ chuyện này sang chuyện kia mà vẫn theo kịp. Chỉ là chẳng ai chịu ngồi xuống chốt một việc, nên kế hoạch thì nhiều mà làm được thì ít.","diem_manh":"Hiểu nhau rất nhanh và không ai thấy người kia nông nổi.","diem_yeu":"Cùng ngại cam kết, cùng dễ chán, cùng né những cuộc nói chuyện nặng.","loi_khuyen":"Viết ra ba việc phải xong trong tháng và dán lên chỗ cả hai cùng thấy."},{"cung_a":"gemini","cung_b":"cancer","diem":3,"loi_binh":"Song Tử dùng đầu, Cự Giải dùng lòng. Song Tử đùa một câu cho vui, Cự Giải mang về nghĩ cả buổi tối. Hai người không ghét nhau, chỉ là mỗi lần cần sự sâu sắc thì lại không gặp nhau ở cùng một chỗ.","diem_manh":"Song Tử làm Cự Giải cười. Cự Giải cho Song Tử sự quan tâm mà họ ít khi nhận được.","diem_yeu":"Cự Giải cần nói sâu, Song Tử lái sang chuyện khác cho nhẹ.","loi_khuyen":"Song Tử ngồi yên nghe hết một lần, không đổi chủ đề giữa chừng."},{"cung_a":"gemini","cung_b":"leo","diem":4,"loi_binh":"Song Tử có cách làm người khác thấy mình thú vị, Sư Tử thì cần đúng thứ đó. Sư Tử toả ra, Song Tử kể lại, và cả hai cùng vui. Đi chơi cùng nhau thì không bao giờ nhạt.","diem_manh":"Sư Tử được tán thưởng, Song Tử được lắng nghe. Hai nhu cầu khớp nhau.","diem_yeu":"Song Tử đùa quá đà, Sư Tử thấy bị hạ thấp trước mặt người khác.","loi_khuyen":"Song Tử giữ lời đùa trong chỗ riêng, đừng bỡn cợt Sư Tử giữa đám đông."},{"cung_a":"gemini","cung_b":"virgo","diem":2,"loi_binh":"Hai cái đầu đều nhanh, chỉ là nhanh về hai hướng ngược nhau. Song Tử nghĩ rộng và bỏ qua chi tiết, Xử Nữ bắt từng chi tiết và khó chịu khi thấy ai đó cẩu thả. Nói chuyện với nhau một lúc là thành tranh cãi.","diem_manh":"Song Tử tìm ra hướng, Xử Nữ làm cho nó chạy được.","diem_yeu":"Xử Nữ thấy Song Tử hời hợt. Song Tử thấy Xử Nữ bới móc.","loi_khuyen":"Chốt một người quyết hướng, một người quyết cách làm, và không lấn sân."},{"cung_a":"gemini","cung_b":"libra","diem":5,"loi_binh":"Hai cung khí gặp nhau, chuyện trò hợp từ câu đầu. Cả hai cùng thích người, thích đi, thích bàn chuyện xa xôi mà không ai thấy phí thời gian. Không khí giữa hai người rất nhẹ. Nhẹ tới mức có lúc chẳng ai biết đối phương đang thật sự nghĩ gì.","diem_manh":"Nói gì cũng hiểu. Hiếm khi phải giải thích lại.","diem_yeu":"Cả hai đều né chuyện nặng, nên vấn đề cứ để đó không ai giải quyết.","loi_khuyen":"Mỗi tháng chọn một chuyện khó rồi nói cho dứt."},{"cung_a":"gemini","cung_b":"scorpio","diem":1,"loi_binh":"Song Tử sống trên bề mặt và thấy thế là đủ vui, còn Bọ Cạp chỉ tin thứ đào xuống tận đáy. Bọ Cạp muốn biết Song Tử thật sự nghĩ gì, mà Song Tử thì hôm nay nghĩ thế này, mai nghĩ thế khác.","diem_manh":"Bọ Cạp kéo Song Tử xuống sâu hơn. Song Tử làm Bọ Cạp nhẹ bớt.","diem_yeu":"Bọ Cạp nghi ngờ, Song Tử thấy bị giám sát rồi càng né.","loi_khuyen":"Song Tử trả lời thẳng một câu hỏi thẳng. Bọ Cạp bớt truy tới cùng."},{"cung_a":"gemini","cung_b":"sagittarius","diem":3,"loi_binh":"Đứng đối nhau mà lại giống nhau ở chỗ ham biết và ham đi, chỉ khác là Song Tử biết rộng còn Nhân Mã muốn biết tới nơi. Cả hai đều dị ứng với ràng buộc nên không ai thấy người kia quá đáng. Hợp nhau để chơi hơn là để xây.","diem_manh":"Nói chuyện không bao giờ chán. Cùng lạc quan, cùng thoáng.","diem_yeu":"Không ai chịu làm người ở lại lo phần còn lại.","loi_khuyen":"Nhận trách nhiệm cụ thể cho từng người, nói miệng là quên ngay."},{"cung_a":"gemini","cung_b":"capricorn","diem":1,"loi_binh":"Ma Kết cần kế hoạch và sự nghiêm túc, Song Tử cần thoáng và vui. Ma Kết thấy Song Tử nói nhiều mà làm chẳng bao nhiêu, còn Song Tử thì thấy Ma Kết nặng nề và già trước tuổi.","diem_manh":"Ma Kết giúp Song Tử đi tới cùng một việc. Song Tử làm Ma Kết bớt căng.","diem_yeu":"Hai cách sống gần như không có điểm giao.","loi_khuyen":"Chọn một việc chung nhỏ rồi làm cho xong, hiểu nhau từ đó."},{"cung_a":"gemini","cung_b":"aquarius","diem":5,"loi_binh":"Mỗi người lạ một kiểu, và không ai thấy cái lạ của người kia là vấn đề. Bảo Bình nghĩ ra điều khác người, Song Tử bắt được ngay và nói tiếp. Không ai đòi hỏi người kia phải báo cáo đi đâu làm gì. Thiếu mỗi phần ngồi xuống nói chuyện lòng dạ.","diem_manh":"Tự do mà vẫn gắn. Hiểu nhau ở chỗ người ngoài không hiểu.","diem_yeu":"Cả hai cùng ngại phần cảm xúc, nên lúc cần dựa thì không biết dựa vào đâu.","loi_khuyen":"Tập nói ra cảm giác thật, dù nghe không được lý trí cho lắm."},{"cung_a":"gemini","cung_b":"pisces","diem":2,"loi_binh":"Song Tử hiểu bằng lời, Song Ngư hiểu bằng linh cảm. Cả hai đều mềm và đều hay đổi ý, nên không ai đủ cứng để giữ cho mọi thứ đứng yên.","diem_manh":"Cả hai đều giàu tưởng tượng và không ai chê người kia viển vông.","diem_yeu":"Song Tử nói đùa, Song Ngư nhận vào thật. Hiểu lầm chất dần.","loi_khuyen":"Song Tử nói rõ lúc nào là đùa. Song Ngư hỏi lại thay vì tự diễn giải."},{"cung_a":"cancer","cung_b":"cancer","diem":4,"loi_binh":"Nặng tình như nhau, nhớ dai như nhau, và cùng coi nhà là chỗ quan trọng nhất. Không ai phải giải thích vì sao hôm nay buồn. Chỉ là khi cả hai cùng tủi thì chẳng còn ai đứng ra làm người dỗ.","diem_manh":"Hiểu cảm xúc của nhau mà không cần nói. Rất ấm.","diem_yeu":"Cùng giận dỗi, cùng im lặng, cùng chờ người kia mở lời trước.","loi_khuyen":"Ai nhận ra trước thì nói trước, đừng tính xem lần trước ai đã nhường."},{"cung_a":"cancer","cung_b":"leo","diem":3,"loi_binh":"Sư Tử cần được nhìn thấy, Cự Giải sẵn lòng nhìn thấy. Sư Tử che chở, Cự Giải chăm sóc, cả hai đều đặt gia đình lên trước, chỉ khác là Sư Tử hướng ra ngoài còn Cự Giải hướng vào trong.","diem_manh":"Cả hai đều ấm và đều muốn lo cho người mình thương.","diem_yeu":"Sư Tử vô tâm đúng lúc Cự Giải đang cần được hỏi han.","loi_khuyen":"Sư Tử hỏi một câu quan tâm mỗi ngày, ngắn cũng được."},{"cung_a":"cancer","cung_b":"virgo","diem":4,"loi_binh":"Cự Giải lo bằng lòng, Xử Nữ lo bằng việc. Xử Nữ ít nói lời ngọt nhưng nhớ hết những thứ nhỏ cần làm. Cự Giải nhận ra điều đó và không đòi hỏi thêm, nên hai người sống với nhau khá dễ chịu.","diem_manh":"Cùng chu đáo, cùng để ý tới người kia. Nhà cửa đâu vào đấy.","diem_yeu":"Xử Nữ góp ý thẳng, Cự Giải nghe thành bị chê.","loi_khuyen":"Xử Nữ nói kèm một câu ghi nhận trước khi góp ý."},{"cung_a":"cancer","cung_b":"libra","diem":2,"loi_binh":"Ghét cãi nhau nên bề ngoài rất êm. Bên trong thì Cự Giải dồn nén còn Thiên Bình lảng tránh. Chuyện cũ không ai mở ra, cứ để đó cho tới lúc nó bật ra một lần rất lớn.","diem_manh":"Hai người cùng dịu dàng, cùng biết nghĩ cho đối phương.","diem_yeu":"Né mãi thành ra chẳng bao giờ giải quyết được gì.","loi_khuyen":"Đặt ra một giờ cố định mỗi tuần để nói những chuyện khó."},{"cung_a":"cancer","cung_b":"scorpio","diem":5,"loi_binh":"Hai cung nước gặp nhau, cảm được nhau trước khi nói ra. Cự Giải cho Bọ Cạp sự an toàn để hạ phòng bị, Bọ Cạp cho Cự Giải cảm giác được chọn trọn vẹn. Gắn rất sâu và rất nhanh. Người ngoài nhìn vào thường thấy khó chen chân.","diem_manh":"Hiểu nhau tới mức người ngoài thấy khó tin. Chung thuỷ cả hai.","diem_yeu":"Hai người cùng nhớ dai, nên vết thương cũ hay bị khơi lại.","loi_khuyen":"Chuyện đã nói xong thì khép lại, đừng lôi ra làm bằng chứng cho lần sau."},{"cung_a":"cancer","cung_b":"sagittarius","diem":1,"loi_binh":"Cự Giải cần biết tối nay người kia ở đâu. Nhân Mã thấy câu hỏi đó là một sợi dây trói. Nhân Mã nói thật tới mức phũ, mà Cự Giải thì nhớ từng chữ.","diem_manh":"Nhân Mã kéo Cự Giải ra khỏi vỏ. Cự Giải cho Nhân Mã một chỗ ấm để về.","diem_yeu":"Một bên cần bám, một bên cần bay. Chuyện này không thoả hiệp dễ.","loi_khuyen":"Nhân Mã chủ động báo tin. Cự Giải bớt hỏi, đợi được báo."},{"cung_a":"cancer","cung_b":"capricorn","diem":3,"loi_binh":"Một bên lo trong nhà, một bên lo ngoài xã hội, đúng kiểu hai cung đứng đối nhau. Ma Kết thể hiện tình cảm bằng việc gánh vác, Cự Giải cần nghe thành lời. Hiểu được cách nhau thì bù nhau rất khéo.","diem_manh":"Ma Kết dựng được nền, Cự Giải giữ được hồn cho cái nền đó.","diem_yeu":"Ma Kết lo việc tới khuya, Cự Giải ngồi nhà thấy mình không quan trọng.","loi_khuyen":"Ma Kết nói ra điều mình đang làm là vì ai. Cự Giải đừng đo tình cảm bằng thời gian."},{"cung_a":"cancer","cung_b":"aquarius","diem":1,"loi_binh":"Cự Giải sống bằng cảm xúc, Bảo Bình phân tích cảm xúc. Lúc Cự Giải cần được ôm thì Bảo Bình đưa ra một lời giải thích hợp lý. Cả hai đều có thiện chí mà vẫn trượt qua nhau.","diem_manh":"Bảo Bình cho Cự Giải cái nhìn tỉnh táo. Cự Giải dạy Bảo Bình cách gần người.","diem_yeu":"Bảo Bình cần khoảng riêng đúng lúc Cự Giải cần được ở gần.","loi_khuyen":"Bảo Bình nói trước khi cần ở một mình, đừng im lặng rút đi."},{"cung_a":"cancer","cung_b":"pisces","diem":5,"loi_binh":"Hai cung nước, mềm gặp mềm. Song Ngư hiểu nỗi buồn của Cự Giải mà không cần hỏi, Cự Giải cho Song Ngư chỗ dựa mà họ vẫn tìm. Sống với nhau rất nhẹ và rất tình. Chỉ là cả hai cùng dễ chìm theo tâm trạng của người kia.","diem_manh":"Đồng cảm gần như tuyệt đối. Không ai phải gồng.","diem_yeu":"Cả hai cùng mềm nên chuyện thực tế không ai đứng ra lo.","loi_khuyen":"Giao hẳn phần tiền nong và giấy tờ cho một người, hoặc nhờ người ngoài."},{"cung_a":"leo","cung_b":"leo","diem":4,"loi_binh":"Hào phóng, ấm áp, và ai cũng muốn người kia hãnh diện về mình. Đi với nhau ở đâu cũng thành tâm điểm. Vấn đề nằm ở chỗ giữa sân khấu chỉ có một chiếc ghế.","diem_manh":"Yêu nhau rất rộng rãi, không tính toán.","diem_yeu":"Cùng sĩ diện. Một câu nói hớ giữa đám đông là chiến tranh lạnh cả tuần.","loi_khuyen":"Thay nhau nhường sân, và khen nhau trước mặt người khác."},{"cung_a":"leo","cung_b":"virgo","diem":3,"loi_binh":"Sư Tử cần lời khen, Xử Nữ lại quen chỉ ra chỗ chưa ổn. Xử Nữ làm thế vì muốn tốt, nhưng Sư Tử nghe ra là bị hạ thấp. Hai người lo cho nhau theo hai ngôn ngữ khác hẳn nhau.","diem_manh":"Xử Nữ lo phần hậu cần rất giỏi, Sư Tử đứng mũi chịu sào rất tốt.","diem_yeu":"Góp ý của Xử Nữ làm Sư Tử tổn thương nhiều hơn họ tưởng.","loi_khuyen":"Xử Nữ khen trước, góp ý sau, và chỉ góp một ý mỗi lần."},{"cung_a":"leo","cung_b":"libra","diem":4,"loi_binh":"Thiên Bình biết cách làm người khác thấy mình quan trọng, mà Sư Tử thì cần đúng điều đó. Cả hai cùng thích đẹp, thích tiệc, thích chỗ đông người. Nhìn vào thấy một cặp rất ăn ảnh.","diem_manh":"Thiên Bình chiều được cái tôi của Sư Tử mà không thấy mất mát gì.","diem_yeu":"Thiên Bình nhường mãi rồi một ngày bỏ đi không báo trước.","loi_khuyen":"Sư Tử hỏi xem Thiên Bình thật sự muốn gì, đừng đợi họ tự nói."},{"cung_a":"leo","cung_b":"scorpio","diem":2,"loi_binh":"Ai cũng mạnh và ai cũng muốn nắm quyền, chỉ khác là Sư Tử nắm công khai còn Bọ Cạp nắm ngầm. Sư Tử sống phô ra, Bọ Cạp giữ kín, nên mỗi bên đều thấy bên kia khó chịu đựng. Hút nhau rất mạnh và va nhau cũng rất mạnh.","diem_manh":"Cùng mãnh liệt, cùng chung thuỷ. Đã yêu là yêu tới cùng.","diem_yeu":"Hai cái tôi lớn cộng với hai cái ghen. Không bên nào chịu thua.","loi_khuyen":"Thống nhất ai quyết việc gì, đừng để tranh giành ngầm."},{"cung_a":"leo","cung_b":"sagittarius","diem":5,"loi_binh":"Hai cung lửa, cùng rộng rãi, cùng lạc quan, cùng thích sống lớn. Nhân Mã nói thẳng mà Sư Tử không giận, vì biết đối phương không có ý xấu. Đi với nhau là vui và rất ít khi nặng nề. Thứ duy nhất cần coi chừng là cái ví.","diem_manh":"Hợp nhau gần như không phải cố. Cùng nhịp, cùng tầm nhìn.","diem_yeu":"Cả hai đều tiêu tay trái, không ai nhắc ai.","loi_khuyen":"Mở một khoản để dành và đừng động vào."},{"cung_a":"leo","cung_b":"capricorn","diem":1,"loi_binh":"Sư Tử làm vì muốn được thấy, Ma Kết làm vì muốn tới đích. Sư Tử thấy Ma Kết lạnh và keo, Ma Kết thấy Sư Tử phô trương và tốn kém. Cả hai đều có tham vọng nhưng không cùng một kiểu.","diem_manh":"Cùng chịu khó và cùng muốn đi xa. Hợp nhau trong công việc hơn là trong nhà.","diem_yeu":"Ma Kết không khen, mà Sư Tử sống bằng lời khen.","loi_khuyen":"Ma Kết nói ra điều mình đánh giá cao ở đối phương, dù chỉ một câu."},{"cung_a":"leo","cung_b":"aquarius","diem":3,"loi_binh":"Sư Tử muốn thuộc về ai đó trọn vẹn, Bảo Bình muốn giữ lại một phần cho riêng mình. Sư Tử nồng, Bảo Bình tỉnh, và đúng cái tỉnh ấy làm Sư Tử vừa bị cuốn vừa bực.","diem_manh":"Bảo Bình cho Sư Tử một góc nhìn mới. Sư Tử sưởi ấm Bảo Bình.","diem_yeu":"Sư Tử cần phản ứng ngay, Bảo Bình lại rút vào im lặng.","loi_khuyen":"Bảo Bình đáp lại bằng cảm xúc. Sư Tử cho Bảo Bình khoảng riêng."},{"cung_a":"leo","cung_b":"pisces","diem":1,"loi_binh":"Sư Tử sống giữa ánh sáng, Song Ngư sống trong thế giới bên trong. Song Ngư ngưỡng mộ Sư Tử thật lòng, nhưng cái ồn ào đó cũng làm họ mệt. Sư Tử thì không hiểu vì sao đối phương cứ rút lui.","diem_manh":"Song Ngư nhìn thấy phần mềm yếu mà Sư Tử giấu rất kỹ.","diem_yeu":"Song Ngư né xung đột, Sư Tử tưởng là thờ ơ.","loi_khuyen":"Song Ngư nói ra lúc thấy quá sức. Sư Tử hạ âm lượng xuống."},{"cung_a":"virgo","cung_b":"virgo","diem":4,"loi_binh":"Để ý chi tiết, lo xa, và muốn mọi thứ đâu ra đấy. Nhà cửa với sổ sách không bao giờ có vấn đề. Chỉ là hai người cùng soi thì chẳng còn chỗ nào được thở.","diem_manh":"Hiểu nhau ở chỗ người khác cho là khó tính.","diem_yeu":"Cùng cầu toàn nên cùng căng. Góp ý qua lại không dứt.","loi_khuyen":"Mỗi tuần một ngày không ai được sửa lưng ai."},{"cung_a":"virgo","cung_b":"libra","diem":3,"loi_binh":"Xử Nữ nói thẳng chỗ chưa ổn, Thiên Bình chỉ muốn không khí đừng căng. Thiên Bình cân nhắc mãi không quyết, Xử Nữ sốt ruột rồi quyết thay, và cứ thế hai người tử tế với nhau mà ít khi thật sự chạm vào nhau.","diem_manh":"Thiên Bình làm mềm cái thẳng của Xử Nữ.","diem_yeu":"Xử Nữ thấy Thiên Bình thiếu dứt khoát, Thiên Bình thấy Xử Nữ hay chê.","loi_khuyen":"Xử Nữ cho Thiên Bình một hạn chót thay vì quyết hộ."},{"cung_a":"virgo","cung_b":"scorpio","diem":4,"loi_binh":"Nhìn thấu người khác là nghề của cả hai, và cũng vì thế mà không ai dễ tin ai. Xử Nữ phân tích, Bọ Cạp cảm nhận, và hai cách đó thường dẫn tới cùng một kết luận. Hợp nhau ở chỗ không ai phải diễn.","diem_manh":"Tin nhau được, và cả hai cùng kín tiếng về chuyện riêng.","diem_yeu":"Cùng hay nghi. Một chuyện nhỏ cũng đủ để cả hai cùng suy diễn.","loi_khuyen":"Hỏi thẳng thay vì tự ghép các mảnh lại với nhau."},{"cung_a":"virgo","cung_b":"sagittarius","diem":2,"loi_binh":"Xử Nữ lên danh sách, Nhân Mã xách ba lô đi luôn. Xử Nữ thấy đối phương ẩu và vô lo, Nhân Mã thấy đối phương vụn vặt và nhát. Hai cách sống này va nhau ở gần như mọi quyết định.","diem_manh":"Nhân Mã kéo Xử Nữ ra khỏi lo lắng. Xử Nữ giữ cho Nhân Mã khỏi hớ.","diem_yeu":"Lời góp ý của Xử Nữ làm Nhân Mã thấy bị quản.","loi_khuyen":"Nhân Mã báo trước kế hoạch. Xử Nữ bớt kiểm tra lại."},{"cung_a":"virgo","cung_b":"capricorn","diem":5,"loi_binh":"Hai cung đất, cùng tận tâm và cùng chu đáo. Ma Kết đặt mục tiêu, Xử Nữ lo cho từng bước tới đó không sai chỗ nào. Cả hai đều ít nói mà làm rất nhiều, nên hiểu nhau không cần dài dòng. Khó khăn ập tới thì đây là cặp đứng vững lâu nhất.","diem_manh":"Đáng tin tuyệt đối với nhau. Làm gì cũng tới nơi tới chốn.","diem_yeu":"Cùng khắt khe với chính mình rồi khắt khe luôn với nhau.","loi_khuyen":"Nhớ nghỉ, và nhớ khen nhau vì những thứ đã làm được."},{"cung_a":"virgo","cung_b":"aquarius","diem":1,"loi_binh":"Xử Nữ muốn mọi thứ theo quy trình, Bảo Bình phá quy trình cho vui. Xử Nữ lo từng chi tiết trước mắt, Bảo Bình nghĩ về chuyện mười năm nữa. Hai cái đầu đều sắc nhưng không bao giờ nhìn về cùng một chỗ.","diem_manh":"Bảo Bình mở ra hướng mới, Xử Nữ biến nó thành thứ chạy được.","diem_yeu":"Xử Nữ thấy Bảo Bình viển vông, Bảo Bình thấy Xử Nữ nhỏ nhặt.","loi_khuyen":"Thống nhất mục tiêu chung trước, cách làm bàn sau."},{"cung_a":"virgo","cung_b":"pisces","diem":3,"loi_binh":"Xử Nữ lý trí và cụ thể, Song Ngư cảm tính và mơ hồ, hai cực của cùng một trục. Xử Nữ giúp Song Ngư đứng vững, Song Ngư dạy Xử Nữ bớt khắt khe. Hút nhau vì mỗi bên có đúng thứ bên kia thiếu.","diem_manh":"Bù nhau rất khéo khi cả hai chịu nhìn nhận chỗ yếu của mình.","diem_yeu":"Xử Nữ sửa lưng, Song Ngư tổn thương rồi rút vào im lặng.","loi_khuyen":"Xử Nữ nói nhẹ đi một nửa. Song Ngư nói ra thay vì lảng."},{"cung_a":"libra","cung_b":"libra","diem":4,"loi_binh":"Dễ chịu, ngại làm mất lòng, nên không khí lúc nào cũng nhẹ. Tới lúc phải chọn một việc thì ai cũng nhường cho người kia quyết, và chuyện cần giải quyết cứ nằm đó.","diem_manh":"Lịch sự và tử tế với nhau, hiếm khi to tiếng.","diem_yeu":"Cùng né. Mâu thuẫn không mất đi, chỉ bị đẩy lùi.","loi_khuyen":"Thay nhau làm người quyết, mỗi tuần một người."},{"cung_a":"libra","cung_b":"scorpio","diem":3,"loi_binh":"Thiên Bình muốn mọi thứ nhẹ nhàng, Bọ Cạp chỉ thấy thật khi đã đi tới tận cùng. Thiên Bình xã giao rộng, Bọ Cạp nhìn vào thấy khó yên tâm. Hai người có thể quý nhau nhưng khó dựa hẳn vào nhau.","diem_manh":"Bọ Cạp cho Thiên Bình chiều sâu, Thiên Bình cho Bọ Cạp sự nhẹ nhõm.","diem_yeu":"Bọ Cạp ghen, Thiên Bình thấy bị trói rồi càng tránh nói thật.","loi_khuyen":"Thiên Bình nói rõ ranh giới của mình. Bọ Cạp tin cho tới khi có lý do để thôi tin."},{"cung_a":"libra","cung_b":"sagittarius","diem":4,"loi_binh":"Thiên Bình thích người, Nhân Mã thích đi, và hai thứ đó ghép lại thành một đời sống khá rộn. Nhân Mã nói thẳng mà Thiên Bình không giận, Thiên Bình khéo léo mà Nhân Mã không thấy giả. Chơi với nhau rất dễ.","diem_manh":"Cùng thoáng, cùng lạc quan, không ai gò ai.","diem_yeu":"Nhân Mã buột miệng, Thiên Bình ngại nói là mình đã chạnh lòng.","loi_khuyen":"Thiên Bình nói ra ngay lúc bị chạm, đừng để dành."},{"cung_a":"libra","cung_b":"capricorn","diem":2,"loi_binh":"Ma Kết đặt công việc lên trước, Thiên Bình cần người bạn đời có mặt. Thiên Bình cân nhắc cho đẹp lòng mọi người, Ma Kết chỉ nhìn vào kết quả. Cả hai đều muốn tiến nhưng không cùng một định nghĩa về tiến.","diem_manh":"Ma Kết cho Thiên Bình sự chắc chắn. Thiên Bình làm đời Ma Kết dễ thở hơn.","diem_yeu":"Ma Kết lạnh và bận, Thiên Bình thấy mình xếp sau công việc.","loi_khuyen":"Ma Kết giữ một buổi tối cố định trong tuần cho đối phương."},{"cung_a":"libra","cung_b":"aquarius","diem":5,"loi_binh":"Hai cung khí, nói chuyện hợp từ đầu và không ai thấy người kia kỳ quặc. Bảo Bình nghĩ khác người, Thiên Bình thấy đó là thú vị chứ không phải vấn đề. Cả hai đều cần bạn bè và không ai đòi người kia ở nhà. Bạn chung thì nhiều, và hai người hợp nhau cả trong vai bạn bè.","diem_manh":"Thoải mái với nhau, hiểu nhau mà không cần giải thích.","diem_yeu":"Cả hai đều lý trí, nên lúc cần một cái ôm thì lại đưa ra một lập luận.","loi_khuyen":"Thỉnh thoảng bỏ lý lẽ sang một bên, chỉ ngồi cạnh nhau."},{"cung_a":"libra","cung_b":"pisces","diem":1,"loi_binh":"Mềm như nhau, cả nể như nhau, và ai cũng ngại làm người khác buồn. Thiên Bình nể bên ngoài, Song Ngư nể bên trong, nên chẳng ai dám nói thật điều mình muốn. Lâu dần cả hai cùng mệt mà không biết vì sao.","diem_manh":"Rất dịu dàng với nhau, không ai làm ai tổn thương cố ý.","diem_yeu":"Không ai chịu trách nhiệm, không ai ra quyết định, không ai nói thật.","loi_khuyen":"Mỗi người viết ra ba điều mình thật sự muốn rồi đưa cho người kia đọc."},{"cung_a":"scorpio","cung_b":"scorpio","diem":4,"loi_binh":"Sâu như nhau, kín như nhau, và nhìn thấu nhau. Không ai lừa được ai một câu nào. Yêu thì mãnh liệt, mà nghi nhau thì cũng không ai gỡ nổi cho ai.","diem_manh":"Gắn bó tới mức người ngoài không chen vào được.","diem_yeu":"Hai cái ghen và hai trí nhớ dai. Một lần tổn thương là nhớ rất lâu.","loi_khuyen":"Nói thẳng điều đang nghi, đừng thử nhau bằng cách im lặng."},{"cung_a":"scorpio","cung_b":"sagittarius","diem":3,"loi_binh":"Bọ Cạp giữ kín, Nhân Mã nói hết. Bọ Cạp cần biết đối phương thuộc về mình, mà Nhân Mã thì dị ứng với chính ý đó, nên quý nhau được nhưng mỗi bên phải bỏ đi một phần bản tính.","diem_manh":"Nhân Mã làm Bọ Cạp nhẹ bớt. Bọ Cạp cho Nhân Mã chiều sâu.","diem_yeu":"Bọ Cạp truy, Nhân Mã né, rồi Bọ Cạp càng truy.","loi_khuyen":"Nhân Mã chủ động chia sẻ. Bọ Cạp bớt kiểm tra."},{"cung_a":"scorpio","cung_b":"capricorn","diem":4,"loi_binh":"Ít nói, làm thật, và không ai tin vào lời hứa suông. Ma Kết lo phần ngoài, Bọ Cạp lo phần trong, và cả hai cùng bền. Người ngoài nhìn vào thường không đoán nổi giữa hai người đang có chuyện gì.","diem_manh":"Rất đáng tin cậy. Đã cam kết là giữ.","diem_yeu":"Cùng kín nên chuyện trong lòng không ai nói ra, cứ nén lại.","loi_khuyen":"Mỗi người nói một điều mình đang nghĩ mà chưa kể, mỗi tuần một lần."},{"cung_a":"scorpio","cung_b":"aquarius","diem":2,"loi_binh":"Bọ Cạp muốn hoà vào nhau, Bảo Bình muốn giữ khoảng cách. Bọ Cạp đòi hỏi sự trung thành tuyệt đối, Bảo Bình coi đó là xâm phạm. Hai người đều rất cứng ở đúng chỗ người kia muốn họ mềm.","diem_manh":"Cả hai đều kiên định và không chạy theo đám đông.","diem_yeu":"Một bên cần gần, một bên cần xa. Giằng co không dứt.","loi_khuyen":"Thoả thuận rõ cái gì là riêng, cái gì là chung, rồi tôn trọng."},{"cung_a":"scorpio","cung_b":"pisces","diem":5,"loi_binh":"Hai cung nước, cảm được nhau mà không cần lời. Song Ngư chấp nhận cả phần tối của Bọ Cạp, Bọ Cạp che chắn cho Song Ngư khỏi thế giới bên ngoài. Người ta hay nói hai cung này sinh ra cho nhau. Điều ít ai nói là cả hai cùng cần một người tỉnh táo đứng bên ngoài.","diem_manh":"Hiểu nhau tới tận đáy. Gắn bó rất sâu và rất nhanh.","diem_yeu":"Cùng chìm trong cảm xúc, nên lúc cả hai cùng xuống thì không ai kéo được ai.","loi_khuyen":"Giữ một người bạn hoặc một thói quen bên ngoài làm điểm tựa."},{"cung_a":"sagittarius","cung_b":"sagittarius","diem":4,"loi_binh":"Ham đi, nói thật, và tin ngày mai sẽ ổn. Chẳng ai hỏi người kia đi đâu, cũng chẳng ai thấy cần báo cáo. Sống với nhau rất thoáng.","diem_manh":"Tự do hoàn toàn mà vẫn thấy gần nhau.","diem_yeu":"Không ai giữ tiền, không ai giữ lịch, không ai chịu phần chán.","loi_khuyen":"Giao hẳn phần sổ sách cho một người, luân phiên cũng được."},{"cung_a":"sagittarius","cung_b":"capricorn","diem":3,"loi_binh":"Nhân Mã sống cho hôm nay, Ma Kết dựng cho mười năm nữa. Ma Kết thấy đối phương vô lo, Nhân Mã thấy đối phương tự làm khổ mình. Hai người không ghét nhau, chỉ là đang đi hai con đường song song.","diem_manh":"Ma Kết giữ cho Nhân Mã không trắng tay. Nhân Mã kéo Ma Kết ra khỏi bàn làm việc.","diem_yeu":"Tiêu tiền và sắp lịch, hai chuyện này không bao giờ thống nhất được.","loi_khuyen":"Chia rõ khoản chung và khoản riêng, rồi không ai nói ai nữa."},{"cung_a":"sagittarius","cung_b":"aquarius","diem":4,"loi_binh":"Không ai trong hai người sống theo khuôn, và cũng chẳng ai thấy đó là chuyện lạ. Bảo Bình nghĩ ra điều lạ, Nhân Mã muốn đi xem thử điều lạ đó. Không ai bắt ai phải ở nhà.","diem_manh":"Rất hợp để cùng nhau khám phá. Không ai thấy ngột ngạt.","diem_yeu":"Cả hai đều ngại phần cam kết và phần thủ tục.","loi_khuyen":"Chốt những điều ràng buộc cần thiết thành văn bản, đừng dựa vào trí nhớ."},{"cung_a":"sagittarius","cung_b":"pisces","diem":2,"loi_binh":"Nhân Mã nói thật tới mức phũ, Song Ngư nhận từng chữ vào lòng. Nhân Mã tiêu thoải mái và không tính, Song Ngư lo mà không dám nói. Thiện chí thì có nhưng cách sống thì va nhau liên tục.","diem_manh":"Cả hai đều rộng lòng và không ai tính toán với người ngoài.","diem_yeu":"Nhân Mã vô tư làm đau, Song Ngư tổn thương rồi im.","loi_khuyen":"Nhân Mã nghĩ một giây trước khi nói. Song Ngư nói ra lúc bị chạm."},{"cung_a":"capricorn","cung_b":"capricorn","diem":4,"loi_binh":"Kỷ luật, chịu khó, và tin rằng làm được rồi mới nói. Kế hoạch nào đặt ra cũng chạy. Chỉ là cả hai cùng cắm đầu vào việc thì chẳng còn mấy thời gian cho nhau.","diem_manh":"Cùng mục tiêu, cùng nhịp, và rất đáng tin.","diem_yeu":"Cùng khô, cùng ngại nói lời tình cảm, cùng lấy công việc làm lý do.","loi_khuyen":"Đặt lịch cho nhau như đặt lịch họp, và giữ đúng lịch đó."},{"cung_a":"capricorn","cung_b":"aquarius","diem":3,"loi_binh":"Ma Kết giữ truyền thống, Bảo Bình muốn làm khác đi. Ma Kết thấy đối phương không thực tế, Bảo Bình thấy đối phương cứng nhắc, nên tôn trọng cái đầu của nhau thì có mà sống chung một nhịp thì khó.","diem_manh":"Ma Kết biến ý tưởng của Bảo Bình thành thứ chạy được.","diem_yeu":"Một bên muốn đi theo đường đã có, một bên muốn mở đường mới.","loi_khuyen":"Thử cách của Bảo Bình trong phạm vi nhỏ trước khi bác bỏ."},{"cung_a":"capricorn","cung_b":"pisces","diem":4,"loi_binh":"Song Ngư mềm, Ma Kết cứng, và hai thứ đó khớp vào nhau khá vừa. Ma Kết lo phần thực tế mà Song Ngư luôn thấy nặng, Song Ngư làm đời Ma Kết bớt lạnh. Không ai thấy phần của người kia là thừa.","diem_manh":"Bù nhau tự nhiên. Ma Kết che chắn, Song Ngư sưởi ấm.","diem_yeu":"Ma Kết nói nặng lời lúc mệt, Song Ngư nhớ rất lâu.","loi_khuyen":"Ma Kết nói lúc đã nguội. Song Ngư đừng tự nhận hết về mình."},{"cung_a":"aquarius","cung_b":"aquarius","diem":4,"loi_binh":"Khác người như nhau, và không ai thấy chuyện đó có gì lạ. Không ai hỏi ai đi đâu, không ai đòi ai trả lời tin nhắn ngay. Tự do thì thừa, chỉ là tự do quá hoá xa cách.","diem_manh":"Hiểu nhau ở chỗ cả hai đều từng bị người khác cho là kỳ quặc.","diem_yeu":"Cùng ngại chuyện tình cảm, nên lâu ngày thành hai người ở chung nhà.","loi_khuyen":"Hẹn nhau một việc chung đều đặn, đừng để ai cũng bận việc riêng."},{"cung_a":"aquarius","cung_b":"pisces","diem":3,"loi_binh":"Bảo Bình giải thích, Song Ngư cảm nhận. Cả hai đều giàu lòng với người ngoài, chỉ là một bên lo cho thế giới bằng lý trí còn một bên bằng trái tim, nên sống cạnh nhau rất êm mà vẫn không thật gần.","diem_manh":"Cùng rộng lòng và cùng không phán xét ai.","diem_yeu":"Song Ngư cần được dỗ, Bảo Bình đưa ra lời phân tích.","loi_khuyen":"Bảo Bình ôm một cái trước khi nói bất cứ điều gì."},{"cung_a":"pisces","cung_b":"pisces","diem":4,"loi_binh":"Nhạy như nhau, mơ như nhau, và cảm được điều người kia chưa kịp nói. Không ai phải gồng trước mặt ai. Chỉ là khi cả hai cùng buồn thì chẳng ai còn đủ sức kéo người kia lên.","diem_manh":"Đồng cảm sâu. Rất ít cặp hiểu nhau nhẹ nhàng như vậy.","diem_yeu":"Cùng trốn chuyện thực tế. Hoá đơn và giấy tờ không ai muốn động vào.","loi_khuyen":"Giao phần thực tế cho một người, hoặc nhờ hẳn người ngoài lo."}];
export const MAU_SO_CHU_DAO = [{"so":1,"ten":"Người dẫn đầu","tinh_cach":"Bạn thuộc kiểu người muốn tự quyết chuyện của mình và khó chịu khi bị bảo phải làm gì. Ở đâu chưa có ai đứng ra, bạn thường là người bước lên.","diem_manh":"Độc lập, dám quyết, không ngại đi trước khi chưa ai đi.","diem_yeu":"Cứng đầu, ngại nhờ vả, dễ thành ra làm một mình cho nhanh.","loi_khuyen":"Việc lớn không ai làm một mình được. Tập giao bớt cho người khác."},{"so":2,"ten":"Người kết nối","tinh_cach":"Bạn nhạy với không khí xung quanh và thường là người làm dịu mọi chuyện. Hợp tác với bạn dễ chịu vì bạn biết lắng nghe thật.","diem_manh":"Tinh tế, kiên nhẫn, giỏi hoà giải và giữ mối quan hệ.","diem_yeu":"Ngại va chạm nên hay nhịn, để bụng rồi mệt một mình.","loi_khuyen":"Nói ra điều mình muốn. Người ta không đoán được đâu."},{"so":3,"ten":"Người kể chuyện","tinh_cach":"Bạn có khiếu diễn đạt và làm không khí quanh mình nhẹ đi. Ý tưởng đến với bạn nhanh, vấn đề là chọn cái nào để làm tới cùng.","diem_manh":"Sáng tạo, hoạt ngôn, dễ gần, truyền được cảm hứng.","diem_yeu":"Cả thèm chóng chán, hay bỏ dở, tránh né chuyện nặng nề.","loi_khuyen":"Chọn một việc và làm cho xong. Bạn thiếu sự bền, không thiếu tài."},{"so":4,"ten":"Người xây nền","tinh_cach":"Bạn tin vào thứ làm được chứ không tin vào lời hứa. Người khác dựa vào bạn vì bạn nói là làm, và làm tới nơi.","diem_manh":"Kỷ luật, đáng tin, chịu khó, làm gì cũng chắc.","diem_yeu":"Cứng nhắc, khó đổi cách, hay lo xa tới mức tự làm khổ mình.","loi_khuyen":"Không phải kế hoạch nào cũng chạy đúng. Chừa chỗ cho việc ngoài dự tính."},{"so":5,"ten":"Người tự do","tinh_cach":"Bạn cần sự thay đổi như người ta cần không khí. Chỗ nào gò bó quá là bạn tìm đường ra, dù chỗ đó đang yên ổn.","diem_manh":"Linh hoạt, thích nghi nhanh, ham học cái mới, không sợ đổi.","diem_yeu":"Thiếu kiên nhẫn, khó cam kết lâu dài, dễ bỏ ngang.","loi_khuyen":"Tự do thật sự là chọn ở lại vì mình muốn, không phải vì bị buộc."},{"so":6,"ten":"Người chăm lo","tinh_cach":"Bạn để ý tới người khác trước khi để ý tới mình. Gia đình và những người thân cận luôn đứng đầu danh sách của bạn.","diem_manh":"Trách nhiệm, ấm áp, người khác thấy an toàn khi ở cạnh bạn.","diem_yeu":"Ôm việc của người khác, can thiệp quá sâu, quên mất bản thân.","loi_khuyen":"Giúp người thì tốt. Nhưng đừng sống thay phần của họ."},{"so":7,"ten":"Người tìm hiểu","tinh_cach":"Bạn không tin điều gì chỉ vì ai đó nói vậy. Bạn cần hiểu tận gốc, và bạn cần khoảng riêng để nghĩ.","diem_manh":"Sâu sắc, tinh ý, phân tích giỏi, không bị đám đông cuốn đi.","diem_yeu":"Xa cách, khó mở lòng, nghĩ nhiều tới mức chậm hành động.","loi_khuyen":"Không phải chuyện gì cũng hiểu xong mới sống được."},{"so":8,"ten":"Người cầm trịch","tinh_cach":"Bạn nhìn ra cơ hội và biết cách biến nó thành kết quả cụ thể. Tiền bạc và quyền quyết định với bạn là công cụ, không phải mục đích.","diem_manh":"Bản lĩnh, nhìn xa, tổ chức tốt, chịu được áp lực lớn.","diem_yeu":"Đặt nặng thành tích, dễ lấn át người khác, khó cho phép mình nghỉ.","loi_khuyen":"Đo đời mình bằng nhiều thước hơn, đừng chỉ bằng kết quả."},{"so":9,"ten":"Người bao dung","tinh_cach":"Bạn nghĩ tới những thứ lớn hơn phần mình, và dễ động lòng trước chuyện của người khác. Có cái gì đó rộng rãi trong cách bạn sống.","diem_manh":"Nhân hậu, nhìn được bức tranh lớn, sẵn lòng cho đi.","diem_yeu":"Cho nhiều rồi thấy hụt, khó buông chuyện cũ, hay lý tưởng hoá.","loi_khuyen":"Muốn giúp được nhiều người thì trước hết đừng để mình cạn."},{"so":11,"ten":"Số chủ 11 — Người truyền cảm hứng","tinh_cach":"Đây là số chủ, mang năng lượng của số 2 nhưng mạnh hơn nhiều. Bạn nhạy cảm khác thường và thường khiến người khác thay đổi cách nghĩ mà không cần cố.","diem_manh":"Trực giác rất tốt, có sức ảnh hưởng, nhìn thấy thứ người khác bỏ qua.","diem_yeu":"Áp lực nội tâm lớn, dễ lo lắng, cảm xúc lên xuống thất thường.","loi_khuyen":"Sự nhạy cảm đó là năng lực, miễn là bạn học cách giữ mình không bị cuốn theo."},{"so":22,"ten":"Số chủ 22 — Người kiến tạo","tinh_cach":"Số mạnh nhất trong thần số học, mang chất của số 4 nhưng ở quy mô lớn. Bạn có khả năng biến một ý tưởng lớn thành thứ tồn tại thật.","diem_manh":"Vừa nhìn xa vừa làm được, kiên trì với những việc nhiều năm mới xong.","diem_yeu":"Tự đặt kỳ vọng quá nặng, dễ kiệt sức, hay thấy mình chưa đủ.","loi_khuyen":"Việc lớn cần thời gian dài. Đừng đòi hỏi mình xong mọi thứ trong một năm."},{"so":33,"ten":"Số chủ 33 — Người thầy","tinh_cach":"Số hiếm gặp nhất, mang chất của số 6 ở mức rộng hơn gia đình. Bạn có xu hướng dìu dắt và chữa lành cho người khác.","diem_manh":"Tấm lòng lớn, kiên nhẫn, truyền được điều tử tế cho người xung quanh.","diem_yeu":"Gánh chuyện của người khác quá nhiều, quên hẳn nhu cầu của mình.","loi_khuyen":"Người chăm sóc cũng cần có người chăm sóc. Đừng ngại nhận."}];
export const MAU_SO_VAN_MENH = [{"so":1,"ten":"Đi con đường riêng","y_nghia":"Cuộc đời đẩy bạn vào những chỗ phải tự quyết. Bạn học được nhiều nhất khi đứng ra chịu trách nhiệm thay vì đi theo người khác.","loi_khuyen":"Khi phân vân, hãy chọn hướng bạn tự chọn được, đừng chọn hướng an toàn nhất."},{"so":2,"ten":"Làm cầu nối","y_nghia":"Vai trò của bạn thường là người ở giữa: nối hai bên lại, làm dịu chuyện căng, giữ cho nhóm không vỡ.","loi_khuyen":"Giá trị của bạn nằm ở chỗ ít ai thấy. Đừng nghĩ rằng vậy là bạn không quan trọng."},{"so":3,"ten":"Diễn đạt và lan toả","y_nghia":"Bạn được sinh ra để nói, viết, kể, hoặc bằng cách nào đó truyền ý tưởng của mình ra ngoài.","loi_khuyen":"Đừng giữ ý tưởng trong đầu. Nó chỉ sống khi bạn đưa nó ra."},{"so":4,"ten":"Dựng thứ bền","y_nghia":"Con đường của bạn là xây từng viên một. Ít hào nhoáng nhưng những gì bạn dựng thường trụ được lâu.","loi_khuyen":"Đừng sốt ruột khi người khác đi nhanh hơn. Họ chưa chắc đi xa hơn."},{"so":5,"ten":"Trải nghiệm và đổi thay","y_nghia":"Đời bạn sẽ có nhiều khúc quanh, nhiều nơi, nhiều nghề. Bạn học qua việc sống chứ không qua sách vở.","loi_khuyen":"Thay đổi nhiều không sao, miễn là mỗi lần đổi bạn có mang theo thứ gì đó."},{"so":6,"ten":"Gánh vác và chăm lo","y_nghia":"Bạn thường là chỗ dựa của gia đình hoặc của một nhóm người. Trách nhiệm tìm đến bạn sớm hơn người khác.","loi_khuyen":"Nhận trách nhiệm thì nhận, nhưng nhớ hỏi xem đó có phải phần của mình không."},{"so":7,"ten":"Tìm hiểu tới tận cùng","y_nghia":"Bạn hợp với những việc cần đào sâu: nghiên cứu, chuyên môn hẹp, hoặc những câu hỏi lớn về đời sống.","loi_khuyen":"Biết nhiều rồi thì nhớ quay lại sống với người khác, đừng ở lì trong đầu mình."},{"so":8,"ten":"Làm chủ nguồn lực","y_nghia":"Con đường của bạn dính tới tiền bạc, tổ chức và quyền quyết định. Bạn học cách dùng nguồn lực sao cho đúng.","loi_khuyen":"Kiếm được là một chuyện. Dùng nó vào đâu mới là chuyện của bạn."},{"so":9,"ten":"Cho đi","y_nghia":"Bạn thường kết thúc một việc gì đó cho người khác, hoặc làm những việc mà lợi ích không quay về mình ngay.","loi_khuyen":"Cho đi mà không mong nhận lại, nhưng cũng đừng để mình cạn kiệt."},{"so":11,"ten":"Thắp sáng cho người khác","y_nghia":"Bạn có khả năng làm người khác nhìn lại chính họ. Ảnh hưởng của bạn thường lớn hơn bạn tưởng.","loi_khuyen":"Muốn soi cho người khác thì bản thân phải đủ vững trước đã."},{"so":22,"ten":"Biến ý lớn thành thật","y_nghia":"Bạn có thể làm những việc mà người khác chỉ nói tới. Con đường này dài và đòi hỏi sự bền bỉ hiếm có.","loi_khuyen":"Chia việc lớn thành từng chặng. Không ai leo hết núi trong một bước."},{"so":33,"ten":"Nâng đỡ người khác","y_nghia":"Con đường của bạn là dạy dỗ, chữa lành, hoặc bằng cách nào đó làm nhẹ gánh cho người xung quanh. Số này rất hiếm.","loi_khuyen":"Cho đi nhiều thì cũng phải biết nhận lại, nếu không bạn sẽ cạn trước khi giúp được ai."}];
export const MAU_MUI_TEN_BIEU_DO = [{"ma":"day-1-5-9","cac_so":"1-5-9","loai":"day","ten":"Quyết tâm","y_nghia":"Nhắm vào thứ gì rồi thì khó ai làm bạn đổi ý. Bạn theo tới cùng kể cả lúc người xung quanh đã bỏ, và phần lớn việc khó trong đời bạn giải quyết được nhờ đúng tính này. Chỗ phải để ý là có lúc bạn giữ một hướng đi quá lâu dù nó đã hết hợp.","loi_khuyen":"Vài tháng một lần, tự hỏi thứ mình đang bám có còn đáng bám không."},{"ma":"day-3-5-7","cac_so":"3-5-7","loai":"day","ten":"Tâm linh","y_nghia":"Bạn cảm được những thứ chưa ai nói ra, và hay quan tâm tới ý nghĩa phía sau sự việc hơn bản thân sự việc. Người có dãy này thường tìm tới thiền, tôn giáo, hoặc đơn giản là những quãng ngồi một mình cho yên. Mặt trái của nó là chìm vào bên trong rồi quên mất chuyện phải sống.","loi_khuyen":"Giữ một việc tay chân đều đặn để kéo mình về mặt đất."},{"ma":"day-3-6-9","cac_so":"3-6-9","loai":"day","ten":"Trí tuệ","y_nghia":"Đầu óc chạy nhanh và nhớ lâu. Bạn học thứ mới không mất nhiều công, thường hiểu vấn đề trước khi người ta giải thích xong. Chỗ dễ vướng là nghĩ nhiều hơn làm, và hay mất kiên nhẫn với người chậm hơn mình.","loi_khuyen":"Biết rồi thì bắt tay vào. Hiểu không thay được làm."},{"ma":"day-2-5-8","cac_so":"2-5-8","loai":"day","ten":"Cân bằng","y_nghia":"Bạn giữ được mình lúc chuyện rối. Người khác tìm tới bạn khi họ hoảng, vì bạn không hoảng theo, và bạn thường là chỗ dựa trong nhà mà không ai nói ra. Chỗ cần coi chừng là bình tĩnh tới mức người ta tưởng bạn dửng dưng.","loi_khuyen":"Thỉnh thoảng cho người thân thấy bạn cũng có lúc không ổn."},{"ma":"day-1-4-7","cac_so":"1-4-7","loai":"day","ten":"Thực tế","y_nghia":"Bạn thích thứ sờ được, đo được, làm xong nhìn thấy kết quả. Tay nghề và kỷ luật là chỗ mạnh, và bạn thường làm tốt những việc người khác thấy khô khan. Chỗ dễ hẹp là coi nhẹ thứ chưa chứng minh được, kể cả khi chúng đúng.","loi_khuyen":"Cho vài thứ chưa đo được một cơ hội. Không mất gì."},{"ma":"day-1-2-3","cac_so":"1-2-3","loai":"day","ten":"Kế hoạch","y_nghia":"Bạn sắp xếp xong trong đầu trước khi bắt tay vào. Giao cho bạn một mớ lộn xộn thì vài hôm sau nó có thứ tự, và bạn nhìn ra chỗ hổng của một kế hoạch khá nhanh. Chỗ dễ căng là bạn khó chịu ra mặt khi người khác phá nhịp.","loi_khuyen":"Chừa sẵn một phương án hai. Đời ít khi chạy đúng bản vẽ."},{"ma":"day-4-5-6","cac_so":"4-5-6","loai":"day","ten":"Ý chí","y_nghia":"Bạn bền. Việc khó tới mấy cũng cứ làm từng chút một cho tới khi xong, và bạn chịu được áp lực lâu hơn phần đông người. Chỗ hay hỏng là ôm quá sức mà không chịu kêu một tiếng.","loi_khuyen":"Nhờ vả không làm bạn yếu đi. Gục mới làm bạn yếu đi."},{"ma":"day-7-8-9","cac_so":"7-8-9","loai":"day","ten":"Hành động","y_nghia":"Bạn làm trước sửa sau. Ngồi yên lâu là bứt rứt nên việc gì tới tay cũng xử lý ngay, và nhờ vậy bạn đi được xa hơn người cùng xuất phát. Chỗ hay mất là vội, và bỏ dở thứ đang làm để chạy sang thứ mới.","loi_khuyen":"Làm xong một việc rồi hẵng mở việc tiếp theo."},{"ma":"trong-1-5-9","cac_so":"1-5-9","loai":"trong","ten":"Trì hoãn","y_nghia":"Bạn biết rõ việc cần làm mà cứ để đó. Không phải lười, bạn làm rất tốt khi đã bắt đầu, nhưng tự khởi động thì khó nếu không có ai thúc sau lưng.","loi_khuyen":"Hẹn hạn chót với một người khác. Hẹn với mình thì dễ dời."},{"ma":"trong-3-5-7","cac_so":"3-5-7","loai":"trong","ten":"Hoài nghi","y_nghia":"Bạn cần bằng chứng mới tin. Ai nói gì cũng để đó xem đã, và chuyện nào không giải thích được thì bạn gạt sang bên. Tính này giữ bạn khỏi bị lừa, đổi lại bạn bỏ lỡ vài thứ chỉ hiểu được sau khi đã thử.","loi_khuyen":"Thử trước, kết luận sau. Thứ tự đó cho bạn nhiều hơn."},{"ma":"trong-3-6-9","cac_so":"3-6-9","loai":"trong","ten":"Trí nhớ kém","y_nghia":"Quên tên người, quên việc vừa định làm, quên đồ để ở đâu. Chuyện này không dính gì tới thông minh, chỉ là đầu bạn không giữ chi tiết lâu.","loi_khuyen":"Ghi ra ngay lúc vừa nghĩ tới. Một cuốn sổ nhỏ gỡ được gần hết."},{"ma":"trong-2-5-8","cac_so":"2-5-8","loai":"trong","ten":"Nhạy cảm","y_nghia":"Bạn để bụng lâu. Một câu nói qua loa của người khác làm bạn nghĩ cả tuần, và bạn hay đoán ra ý xấu ở chỗ người ta chẳng có ý gì.","loi_khuyen":"Hỏi thẳng người đó. Câu trả lời thường nhẹ hơn bạn tưởng nhiều."},{"ma":"trong-1-4-7","cac_so":"1-4-7","loai":"trong","ten":"Lộn xộn","y_nghia":"Bàn bừa, giấy tờ không biết ở đâu, hẹn giờ hay trễ. Bạn vẫn làm được việc, chỉ là cách làm không theo một trật tự nào người ngoài nhìn ra được.","loi_khuyen":"Chọn một chỗ cố định cho chìa khoá, ví, giấy tờ. Chỉ một chỗ thôi."},{"ma":"trong-1-2-3","cac_so":"1-2-3","loai":"trong","ten":"Thiếu chuẩn bị","y_nghia":"Bạn hay nhảy vào việc rồi mới tính. Nhiều lần may thì xong, nhưng cũng nhiều lần tới giữa đường mới phát hiện thiếu thứ đáng ra phải lo từ đầu.","loi_khuyen":"Dành mười phút liệt kê thứ cần trước khi bắt đầu. Mười phút đó rẻ."},{"ma":"trong-4-5-6","cac_so":"4-5-6","loai":"trong","ten":"Bức bối","y_nghia":"Bạn muốn nhiều thứ cùng lúc và thấy không thứ nào chạy đủ nhanh. Cảm giác bị kẹt lại cứ quay về, rõ nhất là những lúc nhìn sang người khác.","loi_khuyen":"Chọn một việc, làm cho xong, rồi mới nhìn sang việc kế."},{"ma":"trong-7-8-9","cac_so":"7-8-9","loai":"trong","ten":"Thụ động","y_nghia":"Bạn chờ đúng thời điểm, chờ đủ điều kiện, chờ người khác đi trước. Cân nhắc kỹ là chỗ hay của bạn, nhưng cơ hội thường không chờ lâu như vậy.","loi_khuyen":"Làm bước nhỏ nhất ngay hôm nay, dù chưa thấy rõ đường."}];
export const MAU_CON_SO_BIEU_DO = [{"so":1,"ten":"Cái tôi","khi_thieu":"Khó nói ra điều mình muốn. Bạn hay nhường cho yên chuyện rồi về nhà mới thấy ấm ức.","khi_co":"Bạn nói được ý mình khi cần, không gắt mà cũng không nhịn.","khi_nhieu":"Cái tôi mạnh và thích tự quyết. Hợp cầm trịch hơn là nhận việc từ người khác."},{"so":2,"ten":"Trực giác","khi_thieu":"Bạn ít để ý cảm xúc người đối diện nên có khi nói thẳng quá mà không hay biết.","khi_co":"Bạn đọc được không khí trong phòng và biết lúc nào thì nên im.","khi_nhieu":"Nhạy tới mức mệt người. Tâm trạng của người xung quanh cứ thấm hết vào bạn."},{"so":3,"ten":"Chữ nghĩa","khi_thieu":"Bạn diễn đạt bằng việc làm dễ hơn bằng lời.","khi_co":"Đầu óc sáng, học nhanh, kể chuyện có duyên.","khi_nhieu":"Nghĩ quá nhiều. Một chuyện nhỏ bạn dựng thành mười tình huống trong đầu."},{"so":4,"ten":"Tay nghề","khi_thieu":"Việc tỉ mỉ lặp đi lặp lại làm bạn nản khá nhanh.","khi_co":"Bạn làm có đầu có đuôi, giao gì cũng yên tâm.","khi_nhieu":"Cày khoẻ, nhưng coi chừng biến mình thành người chỉ còn biết làm."},{"so":5,"ten":"Cảm xúc","khi_thieu":"Bạn giấu cảm xúc kỹ, kể cả với người thân trong nhà.","khi_co":"Vui buồn rõ ràng và bạn nói ra được.","khi_nhieu":"Cảm xúc lên xuống mạnh. Yêu ghét gì cũng hết mình."},{"so":6,"ten":"Trách nhiệm","khi_thieu":"Bạn ngại gánh phần của người khác, thích ai lo việc nấy.","khi_co":"Bạn lo được cho người quanh mình mà không thấy nặng.","khi_nhieu":"Ôm hết vào người rồi tự thấy chẳng ai hiểu cho mình."},{"so":7,"ten":"Vốn sống","khi_thieu":"Đường bạn đi tương đối phẳng, chưa gặp cú vấp nào đủ lớn để nhớ đời.","khi_co":"Bạn rút được bài học từ chuyện đã qua thay vì nhắc lại nó.","khi_nhieu":"Bạn đi qua nhiều chuyện không dễ kể. Vốn sống dày, và cái giá cũng trả rồi."},{"so":8,"ten":"Tiền bạc","khi_thieu":"Sổ sách và con số chưa bao giờ là chỗ mạnh của bạn.","khi_co":"Bạn tính toán rõ ràng, thu chi có kiểm soát.","khi_nhieu":"Giỏi xoay tiền và bày việc, nhưng dễ lấy tiền làm thước đo cho mọi thứ."},{"so":9,"ten":"Lòng với người","khi_thieu":"Bạn thực tế, ít bị cuốn theo những chuyện lý tưởng xa vời.","khi_co":"Bạn để tâm tới những chuyện lớn hơn bản thân mình.","khi_nhieu":"Giàu lòng trắc ẩn tới mức hay quên mất chính mình."}];
export const MAU_TU_VI = [{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":0,"noi_dung":"Máu lửa trong người đang lên cao. Đây là ngày hợp để bắt đầu thứ bạn hoãn mãi, nhưng nhớ nhìn xuống chân trước khi nhảy."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":1,"noi_dung":"Có người sẽ nói điều làm bạn nóng mặt. Đếm tới ba trước khi đáp lại, chỉ ba giây thôi là đủ đổi cả cục diện."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":2,"noi_dung":"Việc gì tới tay hôm nay cũng xong nhanh. Tận dụng buổi sáng, chiều tối sức bạn tụt rõ."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":3,"noi_dung":"Bạn đang muốn quyết một chuyện lớn. Hôm nay hỏi thêm một người nữa rồi hẵng chốt."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":4,"noi_dung":"Ai đó chậm hơn bạn và điều đó làm bạn bực. Họ không sai, chỉ là không cùng nhịp."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":5,"noi_dung":"Một cơ hội tới bất ngờ và không chờ bạn cân nhắc lâu. Lần này cứ tin bụng mình."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":6,"noi_dung":"Hôm nay bạn dễ nói ra điều lúc bình thường giữ lại được. Nghĩ xem câu đó có cần nói không."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":7,"noi_dung":"Sức bạn đang dồi dào nhưng đang rải ra quá nhiều chỗ. Chọn một việc, làm cho xong."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":8,"noi_dung":"Có chuyện cũ quay lại đòi bạn giải quyết. Lần này đừng né nữa."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":9,"noi_dung":"Người khác đang chờ bạn đi trước. Bạn vốn giỏi phần đó, cứ bước đi."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":10,"noi_dung":"Một lời khen tới từ chỗ bạn không ngờ. Nhận cho tử tế, đừng gạt đi."},{"ky":"ngay","muc":"tong_quan","cung":"aries","thu_tu":11,"noi_dung":"Hôm nay thắng được một cuộc tranh luận mà mất một người bạn thì không đáng. Cân nhắc."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":0,"noi_dung":"Nhịp chậm của bạn hôm nay lại là lợi thế. Trong khi người khác vội, bạn thấy được chỗ họ bỏ sót."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":1,"noi_dung":"Có người giục bạn quyết nhanh. Bạn không nợ ai một câu trả lời ngay lập tức."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":2,"noi_dung":"Một khoản chi đang nằm trong đầu bạn mấy hôm nay. Hôm nay là ngày tốt để tính cho ra nhẽ."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":3,"noi_dung":"Bạn đang giữ chặt một thứ đã hết cần giữ. Buông ra nhẹ hơn bạn tưởng."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":4,"noi_dung":"Hôm nay hợp với những việc làm bằng tay và nhìn thấy kết quả ngay. Dọn nhà cũng tính."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":5,"noi_dung":"Ai đó thay đổi kế hoạch vào phút chót và bạn khó chịu. Khó chịu là đúng, nhưng đừng để nó kéo cả ngày."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":6,"noi_dung":"Một bữa ăn ngon hoặc một giấc ngủ đủ sẽ sửa được phần lớn thứ đang làm bạn nặng đầu."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":7,"noi_dung":"Bạn bướng ở chỗ không đáng bướng. Nghe hết câu của người ta rồi hẵng cãi."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":8,"noi_dung":"Thứ bạn xây lâu nay đang bắt đầu có hình. Người khác chưa thấy, nhưng bạn thấy."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":9,"noi_dung":"Hôm nay có người nhờ vả. Giúp được thì giúp, nhưng đừng nhận quá sức."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":10,"noi_dung":"Cái cũ kỹ trong thói quen của bạn đang cản đường. Thử một cách khác đúng một lần."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":11,"noi_dung":"Tiền vào hoặc tin về tiền. Đừng tiêu ngay, để qua đêm rồi tính."},{"ky":"ngay","muc":"tong_quan","cung":"taurus","thu_tu":12,"noi_dung":"Người thân cần bạn có mặt hơn là cần bạn lo liệu. Ngồi xuống với họ."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":0,"noi_dung":"Đầu bạn chạy nhanh hơn miệng hôm nay, mà miệng bạn vốn đã nhanh. Nói ít đi một chút."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":1,"noi_dung":"Một cuộc trò chuyện tình cờ mở ra thứ bạn đang tìm. Để ý người bạn ít khi nói chuyện cùng."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":2,"noi_dung":"Bạn đang mở quá nhiều việc cùng lúc. Đóng bớt hai cái, giữ lại cái đáng."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":3,"noi_dung":"Có tin tới và bạn muốn kể lại ngay. Kiểm xem đã đúng chưa đã."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":4,"noi_dung":"Hôm nay hợp để học hoặc đọc thứ gì đó mới. Não bạn đang bắt sóng tốt."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":5,"noi_dung":"Ai đó cần bạn ngồi yên và nghe hết, không chen vào. Khó với bạn, nhưng làm được."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":6,"noi_dung":"Bạn thấy chán một việc đang làm dở. Cố nốt hôm nay, mai nhìn lại sẽ khác."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":7,"noi_dung":"Một lời nói đùa của bạn có thể làm người ta nghĩ ngợi. Để ý nét mặt họ."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":8,"noi_dung":"Có hai lựa chọn và bạn muốn cả hai. Hôm nay buộc phải chọn một."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":9,"noi_dung":"Bạn đang tránh một cuộc nói chuyện khó. Nó sẽ không tự dễ đi."},{"ky":"ngay","muc":"tong_quan","cung":"gemini","thu_tu":10,"noi_dung":"Việc giấy tờ hoặc liên lạc hôm nay dễ sót. Đọc lại trước khi gửi."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":0,"noi_dung":"Lòng bạn hôm nay nặng hơn mức việc đáng. Chuyện có thể không tệ như bạn đang nghĩ."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":1,"noi_dung":"Một người cũ nhắc tới bạn. Tin đó làm bạn vui hơn bạn chịu thừa nhận."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":2,"noi_dung":"Nhà cửa và người nhà là chỗ bạn nên dồn sức hôm nay. Mấy chuyện ngoài kia chờ được."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":3,"noi_dung":"Bạn đang giữ trong bụng một câu chưa nói. Nói ra đi, giữ thêm nữa là thành vết."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":4,"noi_dung":"Có người cần bạn chăm sóc, nhưng hôm nay bạn mới là người cần được chăm."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":5,"noi_dung":"Một chuyện nhỏ chạm vào ký ức cũ. Nhận ra là nó cũ, rồi đi tiếp."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":6,"noi_dung":"Trực giác bạn hôm nay nhạy. Thứ bạn linh cảm về một người thường là đúng."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":7,"noi_dung":"Bạn nhớ dai, và điều đó đang làm bạn mệt. Có chuyện đáng để quên."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":8,"noi_dung":"Ai đó nói một câu vô tâm. Họ không có ý gì cả, thật đấy."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":9,"noi_dung":"Hôm nay hợp để nấu ăn, dọn dẹp, hoặc gọi về cho bố mẹ."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":10,"noi_dung":"Bạn muốn rút vào vỏ. Cho mình nửa ngày yên rồi hẵng quay ra."},{"ky":"ngay","muc":"tong_quan","cung":"cancer","thu_tu":11,"noi_dung":"Một khoản tiết kiệm hoặc một chuyện liên quan tới nhà cửa có tiến triển."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":0,"noi_dung":"Hôm nay có người nhìn vào bạn. Cứ là chính mình, bạn không cần diễn."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":1,"noi_dung":"Một lời khen bạn đang chờ có thể không tới. Điều đó không làm việc bạn làm kém đi."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":2,"noi_dung":"Bạn rộng rãi tới mức quên phần mình. Giữ lại một chút cho bản thân."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":3,"noi_dung":"Có chuyện chạm vào sĩ diện. Bỏ qua được thì bỏ, nó nhỏ hơn bạn đang thấy."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":4,"noi_dung":"Hôm nay hợp để đứng ra cầm trịch một việc. Người khác đang chờ ai đó làm việc đó."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":5,"noi_dung":"Ai đó cần bạn nhường sân khấu. Nhường một lần không mất gì."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":6,"noi_dung":"Bạn đang tiêu nhiều hơn mức cần để trông cho đẹp. Cân lại."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":7,"noi_dung":"Một người trẻ hơn hoặc ít kinh nghiệm hơn cần bạn chỉ đường. Cho họ thời gian."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":8,"noi_dung":"Năng lượng bạn hôm nay kéo được cả nhóm. Dùng nó vào việc đáng."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":9,"noi_dung":"Có lời phê bình và bạn nghe ra là chê bai. Nghe lại lần nữa, có khi họ đang giúp."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":10,"noi_dung":"Hôm nay nên làm một việc cho vui, không vì ai nhìn thấy cả."},{"ky":"ngay","muc":"tong_quan","cung":"leo","thu_tu":11,"noi_dung":"Chuyện tình cảm có tin tốt. Chủ động một bước là xong."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":0,"noi_dung":"Bạn đang thấy mọi chỗ cần sửa. Hôm nay sửa đúng một chỗ thôi, chỗ quan trọng nhất."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":1,"noi_dung":"Một chi tiết nhỏ bạn phát hiện ra cứu được cả việc lớn. Nói ra cho người ta biết."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":2,"noi_dung":"Bạn khắt khe với chính mình hơn mức cần. Thứ bạn làm hôm qua đã đủ tốt."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":3,"noi_dung":"Có người làm ẩu và bạn phải dọn. Nói thẳng một lần còn hơn im rồi ấm ức."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":4,"noi_dung":"Hôm nay hợp để sắp xếp lại thứ đang lộn xộn. Giấy tờ, tủ đồ, danh sách việc."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":5,"noi_dung":"Bạn lo một chuyện chưa xảy ra. Viết nó ra giấy, nhìn vào sẽ thấy nó bé hơn."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":6,"noi_dung":"Sức khoẻ cần được để ý. Thứ bạn vẫn hoãn khám thì hôm nay đặt lịch đi."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":7,"noi_dung":"Một lời góp ý của bạn vào tai người khác nặng hơn bạn tưởng. Nói mềm hơn một nhịp."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":8,"noi_dung":"Việc bạn làm âm thầm lâu nay hôm nay có người nhìn thấy."},{"ky":"ngay","muc":"tong_quan","cung":"virgo","thu_tu":9,"noi_dung":"Bạn đang chờ mọi thứ hoàn hảo rồi mới bắt đầu. Bắt đầu lúc còn chưa hoàn hảo đi."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":0,"noi_dung":"Bạn đang cân nhắc quá lâu một chuyện. Chọn đại một bên, cả hai đều sống được."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":1,"noi_dung":"Có người làm bạn khó xử và bạn đang chiều để yên chuyện. Yên hôm nay, mệt ngày mai."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":2,"noi_dung":"Hôm nay hợp để làm lành. Một tin nhắn ngắn là đủ."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":3,"noi_dung":"Bạn thấy mình đang gánh phần của người khác. Trả lại cho họ."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":4,"noi_dung":"Cái đẹp hôm nay chữa được tâm trạng bạn. Dọn bàn, mua hoa, nghe nhạc gì đó tử tế."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":5,"noi_dung":"Có hai bên và ai cũng muốn bạn đứng về phía họ. Bạn được quyền đứng ngoài."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":6,"noi_dung":"Một chuyện hợp tác có tiến triển. Nhớ ghi lại cho rõ ai làm gì."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":7,"noi_dung":"Bạn nhịn mãi và sắp bật. Nói ra lúc còn nhẹ thì nó còn là lời nói."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":8,"noi_dung":"Người ấy đang chờ bạn chủ động. Họ sẽ không nói ra đâu."},{"ky":"ngay","muc":"tong_quan","cung":"libra","thu_tu":9,"noi_dung":"Hôm nay bạn dễ bị cuốn theo ý người khác. Hỏi lại xem mình thật sự muốn gì."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":0,"noi_dung":"Bạn đang nghi một chuyện. Hỏi thẳng còn hơn ngồi ghép các mảnh lại với nhau."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":1,"noi_dung":"Có thứ bạn giữ kín lâu nay. Hôm nay có người đáng để bạn kể."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":2,"noi_dung":"Trực giác bạn đúng, nhưng cách bạn định phản ứng thì hơi quá tay."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":3,"noi_dung":"Một chuyện cũ bạn tưởng đã xong lại ngoi lên. Lần này khép cho hẳn."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":4,"noi_dung":"Hôm nay bạn nhìn thấu người đối diện. Biết rồi thì không nhất thiết phải nói ra."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":5,"noi_dung":"Bạn đang nắm chặt một chuyện không còn đáng nắm. Thả tay là nhẹ ngay."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":6,"noi_dung":"Có người thử lòng tin của bạn. Cho họ một cơ hội nữa, nhưng chỉ một."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":7,"noi_dung":"Việc cần đào sâu và kiên nhẫn hôm nay hợp với bạn hơn ai hết."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":8,"noi_dung":"Bạn im lặng và người kia hiểu thành giận. Nói một câu cho rõ."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":9,"noi_dung":"Tiền bạc hoặc chuyện chung đụng tài sản cần bạn nhìn kỹ hôm nay."},{"ky":"ngay","muc":"tong_quan","cung":"scorpio","thu_tu":10,"noi_dung":"Một thay đổi bạn vẫn sợ hoá ra lại là lối ra. Dám nghĩ tới nó đi."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":0,"noi_dung":"Bạn muốn đi đâu đó. Nếu chưa đi xa được thì đổi đường về nhà cũng đỡ."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":1,"noi_dung":"Lời bạn nói hôm nay thẳng quá mức cần thiết. Thật lòng không có nghĩa là nói hết."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":2,"noi_dung":"Có cơ hội mở ra ở chỗ xa hoặc từ người lạ. Để ý."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":3,"noi_dung":"Bạn đang hứa nhiều hơn mức giữ được. Rút bớt một lời là tử tế hơn."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":4,"noi_dung":"Hôm nay hợp để học thứ gì đó chẳng liên quan tới công việc. Não bạn cần món đó."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":5,"noi_dung":"Một ràng buộc đang làm bạn ngột. Nói ra thay vì lặng lẽ bỏ đi."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":6,"noi_dung":"Người khác đang cần đúng sự lạc quan của bạn. Chia cho họ một ít."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":7,"noi_dung":"Bạn bỏ dở mấy việc rồi. Chọn một cái quay lại làm nốt."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":8,"noi_dung":"Tiền ra nhanh hơn tiền vào mấy hôm nay. Nhìn lại một lượt."},{"ky":"ngay","muc":"tong_quan","cung":"sagittarius","thu_tu":9,"noi_dung":"Có người nói bạn vô tâm. Họ không hẳn sai, nghe thử xem."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":0,"noi_dung":"Bạn làm nhiều quá rồi. Hôm nay nghỉ sớm một buổi không ai sập cả."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":1,"noi_dung":"Một việc bạn kiên trì lâu nay bắt đầu có kết quả. Chưa to, nhưng là thật."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":2,"noi_dung":"Người nhà cần bạn có mặt, không cần bạn lo tiền. Hai thứ đó khác nhau."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":3,"noi_dung":"Bạn đang khắt khe với một người theo cách bạn khắt khe với mình. Họ không chịu nổi như bạn."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":4,"noi_dung":"Hôm nay hợp để tính đường dài: kế hoạch, hợp đồng, chuyện vài năm nữa."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":5,"noi_dung":"Có người cấp trên hoặc lớn tuổi hơn để ý tới bạn. Chuyện này có lợi về sau."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":6,"noi_dung":"Bạn ngại nói lời tình cảm. Hôm nay nói một câu thôi cũng được."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":7,"noi_dung":"Một quy củ bạn đang giữ đã hết tác dụng. Dám bỏ nó đi."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":8,"noi_dung":"Việc nặng hôm nay cứ chia nhỏ ra. Bạn vốn giỏi phần đó."},{"ky":"ngay","muc":"tong_quan","cung":"capricorn","thu_tu":9,"noi_dung":"Thành quả của bạn ít người thấy. Điều đó không làm nó bớt thật."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":0,"noi_dung":"Bạn nghĩ ra thứ chưa ai làm. Nói ra đi, đừng giữ trong đầu rồi tự thấy kỳ."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":1,"noi_dung":"Có người cần bạn ở gần, mà bạn thì đang muốn ở một mình. Nói cho họ biết, đừng lặng lẽ rút."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":2,"noi_dung":"Hôm nay đám đông làm bạn mệt. Tìm chỗ yên nửa tiếng là người lại."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":3,"noi_dung":"Một chuyện ai cũng làm theo cách cũ, bạn thấy cách khác tốt hơn. Thử trong phạm vi nhỏ trước."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":4,"noi_dung":"Bạn phân tích cảm xúc thay vì cảm nhận nó. Hôm nay cho phép mình cảm trước."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":5,"noi_dung":"Bạn bè hoặc một nhóm nào đó cần bạn. Có mặt một lúc thôi cũng đủ."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":6,"noi_dung":"Có thứ bạn làm vì nguyên tắc chứ không vì muốn. Hỏi lại nguyên tắc đó còn đúng không."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":7,"noi_dung":"Hôm nay hợp với công nghệ, máy móc, hoặc thứ gì cần đầu óc lạnh."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":8,"noi_dung":"Người ta hiểu nhầm ý bạn. Giải thích một lần, không cần hơn."},{"ky":"ngay","muc":"tong_quan","cung":"aquarius","thu_tu":9,"noi_dung":"Một kế hoạch dài hạn cần bạn ngồi xuống viết ra cho cụ thể."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":0,"noi_dung":"Bạn thấm tâm trạng người xung quanh nhiều quá. Hôm nay giữ lại một phần cho mình."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":1,"noi_dung":"Có người nhờ và bạn định gật cho xong. Nghĩ thêm một nhịp rồi hẵng trả lời."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":2,"noi_dung":"Trực giác bạn đang chỉ đúng hướng, chỉ là bạn chưa dám tin nó."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":3,"noi_dung":"Hôm nay hợp với thứ cần tưởng tượng: viết, vẽ, nhạc, hoặc chỉ là mơ cho ra chuyện."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":4,"noi_dung":"Bạn đang trốn một việc thực tế. Làm xong nó mất ít thời gian hơn là né nó."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":5,"noi_dung":"Một câu nói làm bạn tổn thương và bạn không nói ra. Người kia không hề biết."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":6,"noi_dung":"Có chuyện buồn cũ ghé qua. Cho nó ngồi một lát rồi tiễn nó đi."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":7,"noi_dung":"Bạn cho đi nhiều rồi. Hôm nay nhận một thứ mà đừng áy náy."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":8,"noi_dung":"Giấc ngủ hôm nay quan trọng hơn mọi việc còn dở."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":9,"noi_dung":"Ai đó thật lòng muốn giúp bạn. Để họ giúp."},{"ky":"ngay","muc":"tong_quan","cung":"pisces","thu_tu":10,"noi_dung":"Tiền bạc cần bạn tỉnh táo hơn thường lệ. Đừng quyết theo cảm giác."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":0,"noi_dung":"Người ấy đang chờ bạn nói trước. Một câu ngắn thôi là đủ mở lời."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":1,"noi_dung":"Có hiểu lầm nhỏ đang lớn dần vì không ai chịu hỏi lại. Hỏi đi."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":2,"noi_dung":"Hôm nay hợp để dành thời gian cho nhau mà không ai cầm điện thoại."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":3,"noi_dung":"Bạn đang đo tình cảm bằng những thứ không đo được. Thôi đếm đi."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":4,"noi_dung":"Nếu đang độc thân, hôm nay dễ gặp người hợp chuyện ở chỗ quen thuộc."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":5,"noi_dung":"Một lời cảm ơn cho thứ người ấy vẫn làm mỗi ngày sẽ đáng giá hơn bạn tưởng."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":6,"noi_dung":"Đừng mang chuyện công việc về nhà rồi trút lên người không liên quan."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":7,"noi_dung":"Có chuyện cũ hai người tránh nhắc tới. Nhắc lúc cả hai đang bình tĩnh thì nó nhẹ."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":8,"noi_dung":"Bạn cần khoảng riêng, và điều đó không có nghĩa là bạn bớt thương ai."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":9,"noi_dung":"Người ấy hôm nay có chuyện riêng. Hỏi han một câu, đừng đoán."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":10,"noi_dung":"Một kỷ niệm cũ quay lại. Vui thì vui, nhưng đừng so với hiện tại."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":11,"noi_dung":"Hợp để làm lành. Ai sai không quan trọng bằng ai chịu mở lời trước."},{"ky":"ngay","muc":"tinh_cam","cung":"chung","thu_tu":12,"noi_dung":"Chuyện tiến xa hơn đang chờ một người quyết. Nếu không phải họ thì là bạn."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":0,"noi_dung":"Việc khó nhất nên làm vào buổi sáng. Để tới chiều là nó không xong nữa."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":1,"noi_dung":"Có người sẽ nhờ bạn ôm thêm phần của họ. Từ chối được thì từ chối."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":2,"noi_dung":"Một chi tiết trong giấy tờ hôm nay cần đọc lại. Sót chỗ đó là phiền về sau."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":3,"noi_dung":"Hợp để trao đổi, thương lượng, hoặc trình bày ý của mình."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":4,"noi_dung":"Bạn đang làm nhiều việc cùng lúc và không việc nào xong. Xếp thứ tự lại."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":5,"noi_dung":"Có cơ hội tới từ người bạn từng làm chung. Giữ liên lạc là có lý do."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":6,"noi_dung":"Hôm nay không phải ngày để quyết chuyện lớn. Thu thập thêm rồi mai hẵng chốt."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":7,"noi_dung":"Công sức của bạn hôm nay có người ghi nhận, dù họ không nói ra."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":8,"noi_dung":"Một mâu thuẫn trong nhóm cần người đứng giữa. Bạn làm được việc đó."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":9,"noi_dung":"Tiền bạc nên tính kỹ hôm nay. Khoản nhỏ cộng lại thành khoản không nhỏ."},{"ky":"ngay","muc":"cong_viec","cung":"chung","thu_tu":10,"noi_dung":"Việc bạn hoãn mãi sẽ chỉ nặng thêm. Làm phần đầu tiên của nó thôi cũng được."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":0,"noi_dung":"Ngủ sớm hơn thường lệ ba mươi phút. Người bạn đang đòi đúng thứ đó."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":1,"noi_dung":"Ngồi lâu quá rồi. Đứng dậy đi một vòng mỗi tiếng."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":2,"noi_dung":"Uống đủ nước. Nghe thì nhàm nhưng hôm nay đúng là bạn đang thiếu."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":3,"noi_dung":"Đầu óc căng thì cơ thể cũng căng theo. Thở chậm vài nhịp."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":4,"noi_dung":"Bữa sáng tử tế hôm nay đổi được cả buổi chiều."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":5,"noi_dung":"Vận động nhẹ hợp hơn tập nặng. Đi bộ là đủ."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":6,"noi_dung":"Mắt bạn mỏi vì nhìn màn hình. Nhìn ra xa mỗi hai mươi phút."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":7,"noi_dung":"Có triệu chứng nhỏ bạn vẫn lờ đi. Hôm nay để ý tới nó."},{"ky":"ngay","muc":"suc_khoe","cung":"chung","thu_tu":8,"noi_dung":"Tâm trạng xuống không phải lúc nào cũng vì chuyện bên ngoài. Có khi chỉ là bạn mệt."},{"ky":"tuan","muc":"tong_quan","cung":"aries","thu_tu":0,"noi_dung":"Tuần này mở ra nhanh và bạn là người châm ngòi. Đầu tuần cứ đẩy tới, nhưng từ giữa tuần nhớ ngoái lại xem có ai theo kịp không."},{"ky":"tuan","muc":"tong_quan","cung":"aries","thu_tu":1,"noi_dung":"Có một chuyện bạn đã nhịn mấy tuần rồi. Tuần này nó sẽ bật ra, nên chọn lúc để nói thay vì để nó tự nổ."},{"ky":"tuan","muc":"tong_quan","cung":"aries","thu_tu":2,"noi_dung":"Nhiều việc cùng đổ về. Tuần này ai sắp xếp được thứ tự thì thắng, mà bạn thì hay bỏ qua đúng khâu đó."},{"ky":"tuan","muc":"tong_quan","cung":"aries","thu_tu":3,"noi_dung":"Giữa tuần có người cản đường bạn. Đi vòng nhẹ nhàng hơn là húc thẳng."},{"ky":"tuan","muc":"tong_quan","cung":"aries","thu_tu":4,"noi_dung":"Tuần hợp để kết thúc một việc dang dở hơn là mở thêm việc mới."},{"ky":"tuan","muc":"tong_quan","cung":"aries","thu_tu":5,"noi_dung":"Sức bạn tuần này lên xuống rõ. Dồn việc nặng vào đầu tuần, cuối tuần để dành cho nghỉ."},{"ky":"tuan","muc":"tong_quan","cung":"taurus","thu_tu":0,"noi_dung":"Tuần này chậm mà chắc là đúng bài của bạn. Ai giục cũng mặc, bạn có nhịp riêng."},{"ky":"tuan","muc":"tong_quan","cung":"taurus","thu_tu":1,"noi_dung":"Chuyện tiền nong cần được nhìn lại một lượt trong tuần. Có khoản đang rò mà bạn chưa để ý."},{"ky":"tuan","muc":"tong_quan","cung":"taurus","thu_tu":2,"noi_dung":"Giữa tuần có thay đổi ngoài dự tính. Khó chịu thật, nhưng nó không phá được thứ bạn đã dựng."},{"ky":"tuan","muc":"tong_quan","cung":"taurus","thu_tu":3,"noi_dung":"Tuần hợp để cải thiện chỗ ở và những thứ bạn dùng hằng ngày. Đầu tư vào đó không phí."},{"ky":"tuan","muc":"tong_quan","cung":"taurus","thu_tu":4,"noi_dung":"Có người muốn bạn nới tay. Nới một chút không làm bạn mất gì."},{"ky":"tuan","muc":"tong_quan","cung":"taurus","thu_tu":5,"noi_dung":"Cuối tuần là lúc thành quả mấy tuần qua bắt đầu hiện ra."},{"ky":"tuan","muc":"tong_quan","cung":"gemini","thu_tu":0,"noi_dung":"Tuần này lời nói của bạn có sức nặng hơn thường lệ. Dùng cho đúng chỗ."},{"ky":"tuan","muc":"tong_quan","cung":"gemini","thu_tu":1,"noi_dung":"Nhiều tin tức và nhiều cuộc gặp. Vui thì vui, nhưng cuối tuần bạn sẽ thấy hụt hơi."},{"ky":"tuan","muc":"tong_quan","cung":"gemini","thu_tu":2,"noi_dung":"Có một việc bạn bỏ dở từ lâu. Tuần này là lúc hợp nhất để quay lại nó."},{"ky":"tuan","muc":"tong_quan","cung":"gemini","thu_tu":3,"noi_dung":"Giữa tuần dễ nói hớ. Đọc lại tin nhắn trước khi bấm gửi."},{"ky":"tuan","muc":"tong_quan","cung":"gemini","thu_tu":4,"noi_dung":"Tuần hợp để học, thi, hoặc trình bày trước đám đông."},{"ky":"tuan","muc":"tong_quan","cung":"gemini","thu_tu":5,"noi_dung":"Bạn đang phân vân giữa hai hướng. Cuối tuần sẽ có thông tin giúp bạn chọn."},{"ky":"tuan","muc":"tong_quan","cung":"cancer","thu_tu":0,"noi_dung":"Tuần này chuyện nhà chiếm phần lớn tâm trí bạn. Giải quyết cho xong rồi hẵng tính chuyện ngoài."},{"ky":"tuan","muc":"tong_quan","cung":"cancer","thu_tu":1,"noi_dung":"Có người cũ xuất hiện trở lại. Gặp hay không là quyền bạn, không ai ép."},{"ky":"tuan","muc":"tong_quan","cung":"cancer","thu_tu":2,"noi_dung":"Đầu tuần bạn dễ tủi vì chuyện không đáng. Giữa tuần nhìn lại sẽ thấy nhẹ."},{"ky":"tuan","muc":"tong_quan","cung":"cancer","thu_tu":3,"noi_dung":"Tuần hợp để nói ra điều bạn giữ trong bụng lâu nay với đúng người."},{"ky":"tuan","muc":"tong_quan","cung":"cancer","thu_tu":4,"noi_dung":"Một khoản liên quan tới nhà cửa hoặc gia đình có tiến triển trong tuần."},{"ky":"tuan","muc":"tong_quan","cung":"cancer","thu_tu":5,"noi_dung":"Bạn lo cho người khác cả tuần rồi. Cuối tuần dành trọn cho mình."},{"ky":"tuan","muc":"tong_quan","cung":"leo","thu_tu":0,"noi_dung":"Tuần này bạn được chú ý. Dùng sự chú ý đó để kéo người khác lên cùng chứ đừng chỉ để toả sáng."},{"ky":"tuan","muc":"tong_quan","cung":"leo","thu_tu":1,"noi_dung":"Có chuyện chạm vào lòng tự trọng giữa tuần. Phản ứng chậm một nhịp là giữ được nhiều thứ."},{"ky":"tuan","muc":"tong_quan","cung":"leo","thu_tu":2,"noi_dung":"Tuần hợp để đứng ra nhận một việc lớn. Người ta đang chờ ai đó bước lên."},{"ky":"tuan","muc":"tong_quan","cung":"leo","thu_tu":3,"noi_dung":"Tiêu pha tuần này dễ quá tay vì bạn muốn mọi thứ tươm tất. Đặt một hạn mức."},{"ky":"tuan","muc":"tong_quan","cung":"leo","thu_tu":4,"noi_dung":"Một lời công nhận bạn chờ đã lâu có thể tới trong tuần."},{"ky":"tuan","muc":"tong_quan","cung":"leo","thu_tu":5,"noi_dung":"Cuối tuần dành cho thứ làm bạn vui thật, không phải thứ trông cho vui."},{"ky":"tuan","muc":"tong_quan","cung":"virgo","thu_tu":0,"noi_dung":"Tuần này mắt bạn tinh hơn người khác. Chỗ bạn thấy sai thường là sai thật, nhưng chọn cách nói."},{"ky":"tuan","muc":"tong_quan","cung":"virgo","thu_tu":1,"noi_dung":"Việc tồn đọng chất lại khá nhiều. Tuần này dọn từng ít một thay vì đợi một ngày rảnh."},{"ky":"tuan","muc":"tong_quan","cung":"virgo","thu_tu":2,"noi_dung":"Giữa tuần bạn dễ căng vì mọi thứ không đúng ý. Hạ chuẩn xuống một bậc là sống dễ hơn hẳn."},{"ky":"tuan","muc":"tong_quan","cung":"virgo","thu_tu":3,"noi_dung":"Tuần hợp để khám sức khoẻ, sắp xếp lại lịch sinh hoạt, hoặc bỏ một thói quen xấu."},{"ky":"tuan","muc":"tong_quan","cung":"virgo","thu_tu":4,"noi_dung":"Có người nhờ bạn kiểm tra giúp. Giúp thì giúp, nhưng đừng làm hộ luôn."},{"ky":"tuan","muc":"tong_quan","cung":"virgo","thu_tu":5,"noi_dung":"Cuối tuần thành quả thầm lặng của bạn được nhìn thấy."},{"ky":"tuan","muc":"tong_quan","cung":"libra","thu_tu":0,"noi_dung":"Tuần này bạn phải chọn, và không chọn cũng là một lựa chọn. Chọn sớm thì đỡ mệt."},{"ky":"tuan","muc":"tong_quan","cung":"libra","thu_tu":1,"noi_dung":"Có hai bên kéo bạn về hai phía. Tuần này tập nói không mà vẫn tử tế."},{"ky":"tuan","muc":"tong_quan","cung":"libra","thu_tu":2,"noi_dung":"Quan hệ hợp tác có tin tốt giữa tuần. Ghi rõ thoả thuận ngay lúc còn vui vẻ."},{"ky":"tuan","muc":"tong_quan","cung":"libra","thu_tu":3,"noi_dung":"Bạn nhịn nhiều rồi. Tuần này nói ra một chuyện, chọn chuyện đáng nhất."},{"ky":"tuan","muc":"tong_quan","cung":"libra","thu_tu":4,"noi_dung":"Tuần hợp với những việc cần sự khéo léo và cân bằng giữa người với người."},{"ky":"tuan","muc":"tong_quan","cung":"libra","thu_tu":5,"noi_dung":"Cuối tuần hợp để làm lành hoặc nối lại một liên lạc đã nguội."},{"ky":"tuan","muc":"tong_quan","cung":"scorpio","thu_tu":0,"noi_dung":"Tuần này có thứ lộ ra. Bạn vốn đã linh cảm từ trước, giờ chỉ là có bằng chứng."},{"ky":"tuan","muc":"tong_quan","cung":"scorpio","thu_tu":1,"noi_dung":"Bạn đang giữ một chuyện quá chặt. Tuần này thử kể cho một người bạn tin."},{"ky":"tuan","muc":"tong_quan","cung":"scorpio","thu_tu":2,"noi_dung":"Giữa tuần dễ nghi ngờ quá đà. Hỏi thẳng trước khi kết luận."},{"ky":"tuan","muc":"tong_quan","cung":"scorpio","thu_tu":3,"noi_dung":"Tuần hợp với việc cần đào sâu, điều tra, hoặc dọn cho dứt một chuyện cũ."},{"ky":"tuan","muc":"tong_quan","cung":"scorpio","thu_tu":4,"noi_dung":"Chuyện tiền chung hoặc tài sản chung cần bạn nhìn kỹ trong tuần."},{"ky":"tuan","muc":"tong_quan","cung":"scorpio","thu_tu":5,"noi_dung":"Cuối tuần một cánh cửa đóng lại, và đó là chuyện tốt."},{"ky":"tuan","muc":"tong_quan","cung":"sagittarius","thu_tu":0,"noi_dung":"Tuần này bạn muốn đi và nên đi. Dù chỉ là đổi chỗ làm việc một buổi."},{"ky":"tuan","muc":"tong_quan","cung":"sagittarius","thu_tu":1,"noi_dung":"Lời bạn nói trong tuần dễ làm ai đó đau mà bạn không biết. Để ý nét mặt người nghe."},{"ky":"tuan","muc":"tong_quan","cung":"sagittarius","thu_tu":2,"noi_dung":"Có cơ hội từ xa hoặc từ người lạ. Trả lời cái tin nhắn bạn đang để đó."},{"ky":"tuan","muc":"tong_quan","cung":"sagittarius","thu_tu":3,"noi_dung":"Giữa tuần bạn thấy bị trói. Nói ra thay vì biến mất."},{"ky":"tuan","muc":"tong_quan","cung":"sagittarius","thu_tu":4,"noi_dung":"Tuần hợp để học thứ mới hoặc lên kế hoạch cho một chuyến đi."},{"ky":"tuan","muc":"tong_quan","cung":"sagittarius","thu_tu":5,"noi_dung":"Cuối tuần nhìn lại ví tiền một lượt, tuần này bạn tiêu tay trái."},{"ky":"tuan","muc":"tong_quan","cung":"capricorn","thu_tu":0,"noi_dung":"Tuần này việc chạy đúng kế hoạch nếu bạn không ôm thêm. Giữ nguyên danh sách ban đầu."},{"ky":"tuan","muc":"tong_quan","cung":"capricorn","thu_tu":1,"noi_dung":"Có người lớn tuổi hơn hoặc cấp trên để mắt tới bạn. Chuyện này có lợi về sau."},{"ky":"tuan","muc":"tong_quan","cung":"capricorn","thu_tu":2,"noi_dung":"Giữa tuần bạn mệt hơn mức chịu thừa nhận. Nghỉ một buổi không ai sập."},{"ky":"tuan","muc":"tong_quan","cung":"capricorn","thu_tu":3,"noi_dung":"Tuần hợp để ký kết, chốt hợp đồng, hoặc tính chuyện vài năm nữa."},{"ky":"tuan","muc":"tong_quan","cung":"capricorn","thu_tu":4,"noi_dung":"Người nhà cần bạn có mặt chứ không cần bạn lo liệu thêm."},{"ky":"tuan","muc":"tong_quan","cung":"capricorn","thu_tu":5,"noi_dung":"Cuối tuần một việc bạn kiên trì lâu nay bắt đầu ra kết quả."},{"ky":"tuan","muc":"tong_quan","cung":"aquarius","thu_tu":0,"noi_dung":"Tuần này ý tưởng của bạn khác người và đúng. Vấn đề là trình bày sao cho người ta nghe."},{"ky":"tuan","muc":"tong_quan","cung":"aquarius","thu_tu":1,"noi_dung":"Bạn cần khoảng riêng nhiều hơn thường lệ. Nói trước cho người thân biết."},{"ky":"tuan","muc":"tong_quan","cung":"aquarius","thu_tu":2,"noi_dung":"Giữa tuần có việc nhóm cần bạn tham gia. Có mặt một lúc cũng đủ."},{"ky":"tuan","muc":"tong_quan","cung":"aquarius","thu_tu":3,"noi_dung":"Tuần hợp với công nghệ, với thứ cần đầu óc lạnh, và với việc dọn lại hệ thống."},{"ky":"tuan","muc":"tong_quan","cung":"aquarius","thu_tu":4,"noi_dung":"Có người hiểu nhầm sự im lặng của bạn thành lạnh nhạt. Giải thích một câu."},{"ky":"tuan","muc":"tong_quan","cung":"aquarius","thu_tu":5,"noi_dung":"Cuối tuần hợp để ngồi xuống viết ra kế hoạch dài hạn cho cụ thể."},{"ky":"tuan","muc":"tong_quan","cung":"pisces","thu_tu":0,"noi_dung":"Tuần này bạn thấm tâm trạng của người xung quanh hơi nhiều. Giữ lại một phần cho mình."},{"ky":"tuan","muc":"tong_quan","cung":"pisces","thu_tu":1,"noi_dung":"Có chuyện thực tế bạn đang trốn. Tuần này làm cho xong, nó nhỏ hơn bạn nghĩ."},{"ky":"tuan","muc":"tong_quan","cung":"pisces","thu_tu":2,"noi_dung":"Trực giác bạn trong tuần rất nhạy. Tin nó, nhưng kiểm lại bằng con số."},{"ky":"tuan","muc":"tong_quan","cung":"pisces","thu_tu":3,"noi_dung":"Giữa tuần dễ bị nhờ vả quá sức. Tập nói lời từ chối."},{"ky":"tuan","muc":"tong_quan","cung":"pisces","thu_tu":4,"noi_dung":"Tuần hợp với việc cần tưởng tượng và cần lòng cảm thông."},{"ky":"tuan","muc":"tong_quan","cung":"pisces","thu_tu":5,"noi_dung":"Cuối tuần có người thật lòng muốn giúp. Để họ giúp."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":0,"noi_dung":"Tuần này hai người cần một buổi nói chuyện tử tế, không vội và không điện thoại."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":1,"noi_dung":"Có chuyện cũ chưa khép lại. Nhắc tới lúc cả hai đang nhẹ nhõm thì nó dễ hơn nhiều."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":2,"noi_dung":"Nếu đang độc thân, giữa tuần là lúc dễ gặp người hợp chuyện nhất."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":3,"noi_dung":"Bạn và người ấy đang lệch nhịp. Không ai sai, chỉ là mỗi người đang bận một thứ."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":4,"noi_dung":"Tuần này một hành động nhỏ nói được nhiều hơn một lời hứa lớn."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":5,"noi_dung":"Có người thứ ba nhiều chuyện quanh mối quan hệ của bạn. Nghe thì nghe, đừng tin ngay."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":6,"noi_dung":"Chuyện tiến thêm một bước đang chờ một người mở lời. Cuối tuần là lúc hợp."},{"ky":"tuan","muc":"tinh_cam","cung":"chung","thu_tu":7,"noi_dung":"Giữ cho mình một khoảng riêng cũng là cách giữ cho quan hệ lâu bền."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":0,"noi_dung":"Đầu tuần dồn sức cho việc khó, cuối tuần để dành cho giấy tờ và việc lặt vặt."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":1,"noi_dung":"Có người sẽ đẩy phần của họ sang bạn trong tuần. Vạch rõ ranh giới ngay từ đầu."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":2,"noi_dung":"Tuần này hợp để thương lượng. Chuẩn bị con số trước khi ngồi vào bàn."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":3,"noi_dung":"Một cơ hội tới từ mối quan hệ cũ. Nhắn hỏi thăm một người bạn lâu chưa gặp."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":4,"noi_dung":"Giữa tuần dễ có trục trặc liên lạc. Xác nhận lại mọi cuộc hẹn."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":5,"noi_dung":"Việc bạn làm âm thầm tuần này bắt đầu có người nhìn thấy."},{"ky":"tuan","muc":"cong_viec","cung":"chung","thu_tu":6,"noi_dung":"Tiền bạc tuần này nên tính theo tháng chứ không theo ngày. Ngồi xuống làm một bảng."}];
